function deep_copy_table(src)
    if type(src) ~= 'table' then return src end
    local dst = {}
    for k, v in pairs(src) do
        dst[k] = deep_copy_table(v)
    end
    return dst
end

function normalize_config_scalar(value, default_value)
    local target_type = type(default_value)
    if target_type == 'boolean' then
        if value == nil then return default_value, true end
        if type(value) == 'boolean' then return value, false end
        if value == 1 or value == '1' or value == 'true' or value == 'TRUE' then return true, true end
        if value == 0 or value == '0' or value == 'false' or value == 'FALSE' then return false, true end
        return default_value, true
    elseif target_type == 'number' then
        local n = tonumber(value)
        if n == nil then return default_value, true end
        return n, type(value) ~= 'number' or n ~= value
    elseif target_type == 'string' then
        if value == nil then return default_value, true end
        if type(value) == 'string' then return value, false end
        return tostring(value), true
    end
    return value, false
end

function normalize_config_table(cfg, defaults)
    if type(cfg) ~= 'table' then
        return deep_copy_table(defaults), true
    end
    local changed = false
    for key, default_value in pairs(defaults) do
        local value = cfg[key]
        if type(default_value) == 'table' then
            local normalized, sub_changed = normalize_config_table(value, default_value)
            cfg[key] = normalized
            if sub_changed then changed = true end
        else
            local normalized, scalar_changed = normalize_config_scalar(value, default_value)
            cfg[key] = normalized
            if scalar_changed then changed = true end
        end
    end
    return cfg, changed
end

