local function tp_is_manual_reconnect_pending()
    return tp_reconnect_state.manual_requested_until ~= nil and tp_reconnect_state.manual_requested_until > os.clock()
end

local function tp_mark_manual_reconnect_request(timeout)
    tp_reconnect_state.manual_requested_until = os.clock() + (timeout or 8.0)
end

local function tp_clear_manual_reconnect_request()
    tp_reconnect_state.manual_requested_until = 0
end


