main_dropdown_anim = 0.0
settings_dropdown_open = false
settings_dropdown_anim = 0.0
content_display_tab = selected_tab
content_target_tab = nil
content_anim = 1.0
content_slide_offset = 0.0
main_submenu_indicator_y = 5.0
main_submenu_indicator_arrival = 1.0
main_submenu_indicator_alpha = 1.0
main_submenu_indicator_active = false
settings_submenu_indicator_y = 5.0
settings_submenu_indicator_arrival = 1.0
settings_submenu_indicator_alpha = 0.0
settings_submenu_indicator_active = false


function request_sidebar_tab(tab)
    if tab == nil then return end
    if selected_tab == nil then
        selected_tab = tab
    end
    if content_display_tab == nil then
        content_display_tab = tab
    end
    if tab == selected_tab and content_target_tab == nil and content_display_tab == tab then
        return
    end
    selected_tab = tab
    if content_display_tab == tab and content_target_tab == nil then
        content_anim = 1.0
        content_slide_offset = 0.0
        return
    end
    content_target_tab = tab
end

function update_content_transition(dt)
    if content_display_tab == nil then
        content_display_tab = selected_tab
    end
    local fade_out_speed = math.min(dt * 10.5, 1.0)
    local fade_in_speed = math.min(dt * 11.5, 1.0)
    if content_target_tab ~= nil then
        if content_display_tab ~= content_target_tab and content_anim > 0.02 then
            content_anim = math.max(0.0, content_anim - fade_out_speed)
        else
            if content_display_tab ~= content_target_tab then
                content_display_tab = content_target_tab
            end
            content_anim = math.min(1.0, content_anim + fade_in_speed)
            if content_anim >= 0.999 then
                content_anim = 1.0
                content_target_tab = nil
            end
        end
    else
        content_anim = math.min(1.0, content_anim + fade_in_speed)
    end
    local eased = content_anim * content_anim * (3.0 - 2.0 * content_anim)
    content_slide_offset = (1.0 - eased) * 10.0
    return eased
end

