function draw_sidebar_chevron(draw_list, center, size, progress, color)
    local arm_x = size * 0.34
    local arm_y = size * 0.42
    local angle = -progress * (math.pi * 0.5)
    local cos_a = math.cos(angle)
    local sin_a = math.sin(angle)
    local function rotate(x, y)
        return x * cos_a - y * sin_a, x * sin_a + y * cos_a
    end
    local ax, ay = rotate(-arm_x, -arm_y)
    local bx, by = rotate(arm_x, 0)
    local cx, cy = rotate(-arm_x, arm_y)
    local thickness = 2.15
    draw_list:AddLine(iv2(center.x + ax, center.y + ay), iv2(center.x + bx, center.y + by), color, thickness)
    draw_list:AddLine(iv2(center.x + bx, center.y + by), iv2(center.x + cx, center.y + cy), color, thickness)
end

function draw_sidebar_button(menu_col, id, pos_x, pos_y, width, height, icon, label, is_active, alpha_mul, is_child, active_progress)
    if active_progress == nil then
        active_progress = is_active and 1.0 or 0.0
    end
    if active_progress < 0.0 then
        active_progress = 0.0
    elseif active_progress > 1.0 then
        active_progress = 1.0
    end

    imgui.SetCursorPos(iv2(pos_x, pos_y))
    local button_pos = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton(id, iv2(width, height))
    local hovered = imgui.IsItemHovered()
    local rect_min = button_pos
    local rect_max = iv2(button_pos.x + width, button_pos.y + height)
    local rounding = is_child and 6 or 7
    local draw_list = imgui.GetWindowDrawList()

    if hovered or active_progress > 0.001 then
        local idle_bg_alpha = is_child and 0.10 or 0.14
        local active_bg_alpha = is_child and 0.18 or 0.24
        local bg_alpha = hovered and idle_bg_alpha or 0.0
        if active_progress > 0.0 then
            bg_alpha = math.max(bg_alpha, idle_bg_alpha + (active_bg_alpha - idle_bg_alpha) * active_progress)
        end
        draw_list:AddRectFilled(
            iv2(rect_min.x + 2, rect_min.y + 1),
            iv2(rect_max.x - 2, rect_max.y - 1),
            menu_col(0.12, 0.12, 0.12, bg_alpha * alpha_mul),
            rounding
        )
    end

    if is_active and not is_child then
        draw_list:AddRectFilled(
            iv2(rect_min.x - 10, rect_min.y),
            iv2(rect_min.x - 6, rect_max.y),
            menu_col(1.0, 1.0, 1.0, alpha_mul)
        )
    end

    local label_alpha = is_child and alpha_mul or 1.0
    local inactive_icon = 0.62
    local active_icon = 1.0
    local inactive_text = 0.72
    local active_text = 1.0
    local icon_gray = inactive_icon + (active_icon - inactive_icon) * active_progress
    local text_gray = inactive_text + (active_text - inactive_text) * active_progress
    local icon_color = menu_col(icon_gray, icon_gray, icon_gray, 0.98 * label_alpha)
    local text_color = menu_col(text_gray, text_gray, text_gray, label_alpha)

    local font_ref = is_child and (fonts[12] or fonts[14]) or fonts[14]
    imgui.PushFont(font_ref)
    local icon_size = imgui.CalcTextSize(icon)
    local label_size = imgui.CalcTextSize(label)
    local icon_x = rect_min.x + (is_child and 14 or 34)
    local label_x = rect_min.x + (is_child and 42 or 66)
    local icon_y = rect_min.y + (height - icon_size.y) * 0.5 - 1
    local label_y = rect_min.y + (height - label_size.y) * 0.5 - 1

    if is_child and active_progress > 0.02 then
        draw_list:AddText(iv2(label_x, label_y + 1), menu_col(0.45, 0.95, 0.45, 0.22 * label_alpha * active_progress), label)
    end
    draw_list:AddText(iv2(icon_x, icon_y), icon_color, icon)
    draw_list:AddText(iv2(label_x, label_y), text_color, label)
    imgui.PopFont()

    return clicked, rect_min, rect_max, hovered
end

function render_sidebar_navigation(dl, win_pos, sidebar_width, dt, menu_col)
    local sidebar_button_width = sidebar_width - 30
    local sidebar_button_height = 40
    local submenu_button_height = 28
    local submenu_indent = 16
    local submenu_row_gap = 2
    local sidebar_row_gap = 4
    local dropdown_speed = math.min(dt * 14.0, 1.0)
    local indicator_speed = math.min(dt * 12.5, 1.0)
    local main_dropdown_target = (main_dropdown_open and 1.0 or 0.0)
    main_dropdown_anim = main_dropdown_anim + (main_dropdown_target - main_dropdown_anim) * dropdown_speed
    if math.abs(main_dropdown_anim - main_dropdown_target) < 0.001 then
        main_dropdown_anim = main_dropdown_target
    end
    local settings_dropdown_target = (settings_dropdown_open and 1.0 or 0.0)
    settings_dropdown_anim = settings_dropdown_anim + (settings_dropdown_target - settings_dropdown_anim) * dropdown_speed
    if math.abs(settings_dropdown_anim - settings_dropdown_target) < 0.001 then
        settings_dropdown_anim = settings_dropdown_target
    end
    local main_dropdown_eased = main_dropdown_anim * main_dropdown_anim * (3.0 - 2.0 * main_dropdown_anim)
    local settings_dropdown_eased = settings_dropdown_anim * settings_dropdown_anim * (3.0 - 2.0 * settings_dropdown_anim)

    local sidebar_cursor_y = 100
    for index, btn in ipairs(sidebar_buttons) do
        local is_selected = (selected_tab == btn.name)

        if btn.dropdown then
            local dropdown_open = main_dropdown_open
            local dropdown_eased = main_dropdown_eased
            local is_dropdown_active = is_main_subtab(selected_tab)

            if btn.state_key == "settings" then
                dropdown_open = settings_dropdown_open
                dropdown_eased = settings_dropdown_eased
                is_dropdown_active = is_settings_subtab(selected_tab)
            end

            local draw_selected = is_selected or is_dropdown_active
            local clicked, rect_min, rect_max, hovered = draw_sidebar_button(
                menu_col,
                "##sidebar_dropdown_" .. tostring(index),
                15,
                sidebar_cursor_y,
                sidebar_button_width,
                sidebar_button_height,
                btn.icon,
                btn.name,
                draw_selected,
                1.0,
                false,
                draw_selected and 1.0 or 0.0
            )

            local arrow_color = draw_selected and menu_col(1.0, 1.0, 1.0, 1.0) or menu_col(0.70, 0.70, 0.70, 1.0)
            if hovered and not draw_selected then
                arrow_color = menu_col(0.88, 0.88, 0.88, 1.0)
            end
            draw_sidebar_chevron(dl, iv2(rect_min.x + 16, rect_min.y + sidebar_button_height * 0.5), 8, dropdown_eased, arrow_color)

            if clicked then
                dropdown_open = not dropdown_open

                if btn.state_key == "settings" then
                    settings_dropdown_open = dropdown_open
                else
                    main_dropdown_open = dropdown_open
                end
            end

            sidebar_cursor_y = sidebar_cursor_y + sidebar_button_height + sidebar_row_gap

            local submenu_content_height = #btn.children * submenu_button_height + math.max(#btn.children - 1, 0) * submenu_row_gap
            local submenu_height = (submenu_content_height + 10) * dropdown_eased
            local submenu_gap = sidebar_row_gap * dropdown_eased

            if submenu_height > 0.75 then
                local submenu_y = sidebar_cursor_y
                imgui.SetCursorPos(iv2(15, submenu_y))
                local submenu_pos = imgui.GetCursorScreenPos()
                dl:AddRectFilled(
                    iv2(submenu_pos.x + 8, submenu_pos.y),
                    iv2(submenu_pos.x + sidebar_button_width - 6, submenu_pos.y + submenu_height),
                    menu_col(0.10, 0.10, 0.10, 0.58 * dropdown_eased),
                    6
                )
                dl:AddLine(
                    iv2(submenu_pos.x + 18, submenu_pos.y + 7),
                    iv2(submenu_pos.x + 18, submenu_pos.y + submenu_height - 7),
                    menu_col(0.35, 0.35, 0.35, 0.78 * dropdown_eased),
                    1.0
                )

                local selected_child_index = 1
                for child_index, child in ipairs(btn.children) do
                    if selected_tab == child.name then
                        selected_child_index = child_index
                        break
                    end
                end
                local indicator_target_y = 5 + (selected_child_index - 1) * (submenu_button_height + submenu_row_gap)
                local indicator_y = indicator_target_y
                local indicator_arrival = 1.0
                local indicator_alpha = 0.0
                local indicator_visible_target = (is_dropdown_active and dropdown_eased > 0.05) and 1.0 or 0.0

                if btn.state_key == "settings" then
                    if is_dropdown_active then
                        if not settings_submenu_indicator_active then
                            settings_submenu_indicator_y = indicator_target_y
                        else
                            settings_submenu_indicator_y = settings_submenu_indicator_y + (indicator_target_y - settings_submenu_indicator_y) * indicator_speed
                            if math.abs(settings_submenu_indicator_y - indicator_target_y) < 0.05 then
                                settings_submenu_indicator_y = indicator_target_y
                            end
                        end
                    end
                    settings_submenu_indicator_alpha = settings_submenu_indicator_alpha + (indicator_visible_target - settings_submenu_indicator_alpha) * math.min(dt * 16.0, 1.0)
                    if math.abs(settings_submenu_indicator_alpha - indicator_visible_target) < 0.01 then
                        settings_submenu_indicator_alpha = indicator_visible_target
                    end
                    settings_submenu_indicator_active = is_dropdown_active
                    indicator_y = settings_submenu_indicator_y
                    indicator_alpha = settings_submenu_indicator_alpha
                else
                    if is_dropdown_active then
                        if not main_submenu_indicator_active then
                            main_submenu_indicator_y = indicator_target_y
                        else
                            main_submenu_indicator_y = main_submenu_indicator_y + (indicator_target_y - main_submenu_indicator_y) * indicator_speed
                            if math.abs(main_submenu_indicator_y - indicator_target_y) < 0.05 then
                                main_submenu_indicator_y = indicator_target_y
                            end
                        end
                    end
                    main_submenu_indicator_alpha = main_submenu_indicator_alpha + (indicator_visible_target - main_submenu_indicator_alpha) * math.min(dt * 16.0, 1.0)
                    if math.abs(main_submenu_indicator_alpha - indicator_visible_target) < 0.01 then
                        main_submenu_indicator_alpha = indicator_visible_target
                    end
                    main_submenu_indicator_active = is_dropdown_active
                    indicator_y = main_submenu_indicator_y
                    indicator_alpha = main_submenu_indicator_alpha
                end

                local indicator_distance = math.abs(indicator_y - indicator_target_y)
                indicator_arrival = 1.0 - math.min(1.0, indicator_distance / 16.0)
                indicator_arrival = indicator_arrival * indicator_arrival * (3.0 - 2.0 * indicator_arrival)

                if btn.state_key == "settings" then
                    settings_submenu_indicator_arrival = indicator_arrival * indicator_alpha
                else
                    main_submenu_indicator_arrival = indicator_arrival * indicator_alpha
                end

                if indicator_alpha > 0.01 then
                    local indicator_top = submenu_pos.y + indicator_y + 4
                    local indicator_bottom = indicator_top + submenu_button_height - 8
                    dl:AddRectFilled(
                        iv2(submenu_pos.x + 10, indicator_top),
                        iv2(submenu_pos.x + 13, indicator_bottom),
                        menu_col(0.95, 0.95, 0.95, 0.95 * dropdown_eased * indicator_alpha),
                        2
                    )
                    dl:AddRectFilled(
                        iv2(submenu_pos.x + 9, indicator_top - 1),
                        iv2(submenu_pos.x + 15, indicator_bottom + 1),
                        menu_col(1.0, 1.0, 1.0, 0.12 * dropdown_eased * indicator_arrival * indicator_alpha),
                        3
                    )
                end

                imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0.0, 0.0, 0.0, 0.0))
                imgui.BeginChild("##sidebar_dropdown_sidebar_" .. tostring(index), iv2(sidebar_button_width, submenu_height), false, imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
                local child_y = 5
                for child_index, child in ipairs(btn.children) do
                    local child_selected = (selected_tab == child.name)
                    local child_active_progress = 0.0
                    if child_selected then
                        child_active_progress = indicator_arrival * indicator_alpha
                    end
                    local child_clicked = draw_sidebar_button(
                        menu_col,
                        "##sidebar_dropdown_child_" .. tostring(index) .. "_" .. tostring(child_index),
                        submenu_indent,
                        child_y,
                        sidebar_button_width - submenu_indent - 10,
                        submenu_button_height,
                        child.icon,
                        child.name,
                        child_selected,
                        dropdown_eased,
                        true,
                        child_active_progress
                    )
                    if child_clicked then
                        request_sidebar_tab(child.name)
                        if btn.state_key == "settings" then
                            settings_dropdown_open = true
                        else
                            main_dropdown_open = true
                        end
                    end
                    child_y = child_y + submenu_button_height + submenu_row_gap
                end
                imgui.EndChild()
                imgui.PopStyleColor()
            end

            sidebar_cursor_y = sidebar_cursor_y + submenu_height + submenu_gap
        else
            local clicked = draw_sidebar_button(
                menu_col,
                "##sidebar_btn_" .. tostring(index),
                15,
                sidebar_cursor_y,
                sidebar_button_width,
                sidebar_button_height,
                btn.icon,
                btn.name,
                is_selected,
                1.0,
                false,
                is_selected and 1.0 or 0.0
            )
            if clicked then
                request_sidebar_tab(btn.name)
            end
            sidebar_cursor_y = sidebar_cursor_y + sidebar_button_height + sidebar_row_gap
        end
    end
end

