last_stuck_action_time = 0
local time_probe_pending = false
local time_probe_pause_until = 0
local time_probe_target = 0
local time_probe_progress = 0
local time_probe_initialized = false
local random_inventory_pending = false
local random_inventory_pause_until = 0
local random_inventory_next_at = 0
local random_inventory_opened = false
local random_inventory_open_at = 0
local current_tree_target = nil
local VK_ESC = 0x1B
local INVENTORY_OPEN_DELAY = 0.25
local INVENTORY_VISIBLE_TIME = 5.0
local SAFE_INVENTORY_STATES = {
    RUN_FIX_ZABOR = true,
    SCAN_FOR_TREE = true,
    RUN_CENTER = true,
    RUN_SDACHA = true,
    RUN_TO_POINT_3 = true,
    RETURN_FROM_FOOD = true
}

local function clamp_time_probe_interval(value)
    value = tonumber(value) or 0
    if value <= 0 then return 0 end
    if value < 3 then return 3 end
    if value > 20 then return 20 end
    return math.floor(value)
end

local function clear_time_probe_state()
    time_probe_pending = false
    time_probe_pause_until = 0
    time_probe_target = 0
    time_probe_progress = 0
    time_probe_initialized = false
end

local function pick_next_time_probe_target()
    local interval = clamp_time_probe_interval(cVARS.time_probe_interval[0])
    cVARS.time_probe_interval[0] = interval
    if interval == 0 then
        time_probe_target = math.random(3, 20)
    else
        time_probe_target = interval
    end
    time_probe_initialized = true
end

local function reset_time_probe_cycle()
    time_probe_pending = false
    time_probe_pause_until = 0
    time_probe_progress = 0
    pick_next_time_probe_target()
end

local function ensure_time_probe_cycle()
    if not time_probe_initialized or time_probe_target < 3 then
        pick_next_time_probe_target()
    end
end

local function get_time_probe_remaining()
    if not time_probe_initialized or time_probe_target < 1 then
        ensure_time_probe_cycle()
    end
    local remaining = time_probe_target - time_probe_progress
    if remaining < 0 then remaining = 0 end
    return remaining
end

local function register_time_probe_success()
    if not cVARS.time_probe_enabled[0] then return end
    ensure_time_probe_cycle()
    time_probe_progress = time_probe_progress + 1
    if time_probe_progress >= time_probe_target then
        time_probe_pending = true
        time_probe_pause_until = os.clock() + 3
        time_probe_progress = 0
    end
end

local function press_key_once(vk, hold_ms)
    hold_ms = hold_ms or 30
    lua_thread.create(function()
        setVirtualKeyDown(vk, true)
        wait(hold_ms)
        setVirtualKeyDown(vk, false)
    end)
end

local function open_inventory()
    sampSendChat('/invent')
end

local function close_inventory()
    press_key_once(VK_ESC, 30)
end

local function set_current_tree_target(tree)
    if tree then
        current_tree_target = {x = tree[1], y = tree[2], z = tree[3]}
    else
        current_tree_target = nil
    end
end

local function clear_random_inventory_state()
    random_inventory_pending = false
    random_inventory_pause_until = 0
    random_inventory_next_at = 0
    random_inventory_opened = false
    random_inventory_open_at = 0
end

local function schedule_next_random_inventory()
    random_inventory_pending = false
    random_inventory_pause_until = 0
    random_inventory_opened = false
    random_inventory_open_at = 0
    if cVARS.random_inventory_enabled[0] then
        random_inventory_next_at = os.clock() + math.random(120, 300)
    else
        random_inventory_next_at = 0
    end
end

local function reset_random_inventory_cycle()
    if cVARS.random_inventory_enabled[0] then
        schedule_next_random_inventory()
    else
        clear_random_inventory_state()
    end
end

local function can_start_random_inventory()
    return cVARS.bot[0]
       and cVARS.random_inventory_enabled[0]
       and SAFE_INVENTORY_STATES[bot_state] == true
       and not time_probe_pending
       and not tp_state.active
       and not tp_state.pending
       and not random_inventory_pending
       and random_inventory_next_at > 0
       and os.clock() >= random_inventory_next_at
       and not isCharInAnyCar(PLAYER_PED)
end

local function begin_random_inventory_cycle()
    random_inventory_pending = true
    random_inventory_opened = false
    random_inventory_open_at = os.clock() + INVENTORY_OPEN_DELAY
    random_inventory_pause_until = random_inventory_open_at + INVENTORY_VISIBLE_TIME
end

local function get_random_inventory_remaining_seconds()
    if random_inventory_pending then
        if not random_inventory_opened then
            return math.max(0, random_inventory_open_at - os.clock())
        else
            return math.max(0, random_inventory_pause_until - os.clock())
        end
    end

    return math.max(0, random_inventory_next_at - os.clock())
end

local function process_random_inventory()
    if can_start_random_inventory() then
        begin_random_inventory_cycle()
    end

    if not random_inventory_pending then
        return false
    end

    walking = false
    setGameKeyState(1, 0)
    setGameKeyState(16, 0)

    if not random_inventory_opened then
        if os.clock() >= random_inventory_open_at then
            open_inventory()
            random_inventory_opened = true
        end
    else
        if os.clock() >= random_inventory_pause_until then
            close_inventory()
            schedule_next_random_inventory()
        end
    end

    return true
end

local function draw_random_inventory_countdown()
    if not cVARS.bot[0] then return end
    if not cVARS.random_inventory_enabled[0] then return end
    if not cVARS.random_inventory_show_remaining[0] then return end

    local text = nil
    local remaining = get_random_inventory_remaining_seconds()

    if random_inventory_pending then
        if not random_inventory_opened then
            text = u8:decode(string.format("Инвентарь откроется через %.1f сек", remaining))
        else
            text = u8:decode(string.format("Инвентарь закроется через %.1f сек", remaining))
        end
    else
        text = u8:decode(string.format("До открытия инвентаря: %.1f сек", remaining))
    end

    local y_offset = 0
    if cVARS.stat_status[0] then
        y_offset = y_offset + 35
    end
    if cVARS.time_probe_enabled[0] and cVARS.time_probe_show_remaining[0] then
        y_offset = y_offset + 15
    end

    renderFontDrawText(font, text, cVARS.x, cVARS.y + y_offset, -1)
end

local elements = {
    radar = {
        pos = {x = 187, y = 553},
        set_pos = false,
        set_pos_offset = {x = 0, y = 0},
        draw_points = {}
    },
    custom = {
        toggle_button = {},
        slider_custom = {},
        checkbox = {},
        input = {},
        slider = {},
        combo = {},
        collapsing = {}
    }
}

function draw_minimal_checkbox_mark(draw_list, center, radius, progress, color)
    if progress <= 0.001 then return end

    local x1 = center.x - radius * 0.45
    local y1 = center.y + radius * 0.02
    local x2 = center.x - radius * 0.12
    local y2 = center.y + radius * 0.34
    local x3 = center.x + radius * 0.52
    local y3 = center.y - radius * 0.42

    local first_t = math.min(progress / 0.45, 1.0)
    local second_t = math.max((progress - 0.45) / 0.55, 0.0)
    local thickness = math.max(1.6, radius * 0.22)

    if first_t > 0 then
        draw_list:AddLine(
            iv2(x1, y1),
            iv2(x1 + (x2 - x1) * first_t, y1 + (y2 - y1) * first_t),
            color,
            thickness
        )
    end

    if second_t > 0 then
        draw_list:AddLine(
            iv2(x2, y2),
            iv2(x2 + (x3 - x2) * second_t, y2 + (y3 - y2) * second_t),
            color,
            thickness
        )
    end
end


function ui_anim_step(current, target, speed)
    local dt = 0.016
    local ok, io = pcall(function() return imgui.GetIO() end)
    if ok and io and io.DeltaTime and io.DeltaTime > 0 then
        dt = io.DeltaTime
    end
    local t = math.min(dt * (speed or 12.0), 1.0)
    return current + (target - current) * t
end

function ui_get_anim_bucket(kind)
    elements.custom[kind] = elements.custom[kind] or {}
    return elements.custom[kind]
end

function ui_get_anim_state(kind, id, defaults)
    local bucket = ui_get_anim_bucket(kind)
    local state = bucket[id]
    if state == nil then
        state = {}
        if defaults then
            for key, value in pairs(defaults) do
                state[key] = value
            end
        end
        bucket[id] = state
    end
    return state
end

local collapsible_content_alpha_multiplier = 1.0
local content_panel_alpha_multiplier = 1.0

function ui_effective_alpha()
    return (ui_alpha_multiplier or 1.0)
        * (collapsible_content_alpha_multiplier or 1.0)
        * (content_panel_alpha_multiplier or 1.0)
end

function ui_control_color(r, g, b, a)
    return conv_c(iv4(r, g, b, (a or 1.0) * ui_effective_alpha()))
end

function ui_push_transparent_frame_style(mode)
    mode = mode or "input"
    local alpha = ui_effective_alpha()
    if mode == "slider" then
        imgui.PushStyleColor(imgui.Col.FrameBg, iv4(0.0, 0.0, 0.0, 0.0))
        imgui.PushStyleColor(imgui.Col.FrameBgHovered, iv4(0.0, 0.0, 0.0, 0.0))
        imgui.PushStyleColor(imgui.Col.FrameBgActive, iv4(0.0, 0.0, 0.0, 0.0))
        imgui.PushStyleColor(imgui.Col.Border, iv4(0.0, 0.0, 0.0, 0.0))
        imgui.PushStyleColor(imgui.Col.SliderGrab, iv4(0.0, 0.0, 0.0, 0.0))
        imgui.PushStyleColor(imgui.Col.SliderGrabActive, iv4(0.0, 0.0, 0.0, 0.0))
        return 6
    end

    imgui.PushStyleColor(imgui.Col.FrameBg, iv4(0.10, 0.10, 0.10, 0.78 * alpha))
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, iv4(0.13, 0.13, 0.13, 0.88 * alpha))
    imgui.PushStyleColor(imgui.Col.FrameBgActive, iv4(0.15, 0.15, 0.15, 0.96 * alpha))
    imgui.PushStyleColor(imgui.Col.Border, iv4(1.0, 1.0, 1.0, 0.0))
    imgui.PushStyleColor(imgui.Col.TextSelectedBg, iv4(1.0, 1.0, 1.0, 0.18 * alpha))
    return 5
end

function ui_pop_transparent_frame_style(count)
    if count and count > 0 then
        imgui.PopStyleColor(count)
    end
end

function ui_draw_control_feedback(kind, id, opts)
    opts = opts or {}
    local state = ui_get_anim_state(kind, id, {hover = 0.0, active = 0.0, open = 0.0, value = 0.0})
    local hovered = imgui.IsItemHovered()
    local active = imgui.IsItemActive()
    state.hover = ui_anim_step(state.hover, hovered and 1.0 or 0.0, opts.hover_speed or 14.0)
    state.active = ui_anim_step(state.active, active and 1.0 or 0.0, opts.active_speed or 16.0)
    if opts.open ~= nil then
        state.open = ui_anim_step(state.open, opts.open and 1.0 or 0.0, opts.open_speed or 10.0)
    end

    if not imgui.GetItemRectMin or not imgui.GetItemRectMax then
        return state
    end

    local rect_min = imgui.GetItemRectMin()
    local rect_max = imgui.GetItemRectMax()
    if rect_min == nil or rect_max == nil then
        return state
    end

    local draw_min_x = rect_min.x
    local draw_max_x = rect_max.x
    if opts.kind == "slider" then
        local label_text = opts.label
        if label_text and label_text ~= "" and not tostring(label_text):match("^##") and imgui.CalcTextSize then
            local ok_size, label_size = pcall(function()
                return imgui.CalcTextSize(label_text)
            end)
            local spacing = 6
            local style = imgui.GetStyle and imgui.GetStyle()
            if style and style.ItemInnerSpacing then
                spacing = style.ItemInnerSpacing.x
            end
            if ok_size and label_size then
                draw_max_x = math.max(draw_min_x + 24, rect_max.x - label_size.x - spacing)
            end
        end
    end

    local draw_min = iv2(draw_min_x, rect_min.y)
    local draw_max = iv2(draw_max_x, rect_max.y)
    local width = draw_max.x - draw_min.x
    local height = draw_max.y - draw_min.y
    if width <= 1 or height <= 1 then
        return state
    end

    local draw_list = imgui.GetWindowDrawList()
    local radius = opts.rounding or 4
    local inset = opts.inset or 1
    local alpha_mul = (opts.alpha or 1.0)

    local glow_alpha = (0.025 + state.hover * 0.035 + state.active * 0.05) * alpha_mul
    local line_alpha = (0.09 + state.hover * 0.08 + state.active * 0.12) * alpha_mul
    if opts.kind == "slider" then
        glow_alpha = (0.035 + state.hover * 0.02 + state.active * 0.03) * alpha_mul
        line_alpha = (0.08 + state.hover * 0.06 + state.active * 0.10) * alpha_mul
    end

    if opts.kind ~= "slider" then
        draw_list:AddRectFilled(
            iv2(draw_min.x + inset, draw_min.y + inset),
            iv2(draw_max.x - inset, draw_max.y - inset),
            ui_control_color(1.0, 1.0, 1.0, glow_alpha),
            radius
        )
        draw_list:AddRect(
            iv2(draw_min.x + inset, draw_min.y + inset),
            iv2(draw_max.x - inset, draw_max.y - inset),
            ui_control_color(1.0, 1.0, 1.0, line_alpha),
            radius,
            0,
            opts.border_thickness or 1.0
        )
    end

    if opts.kind == "slider" and opts.min ~= nil and opts.max ~= nil then
        local denom = (opts.max - opts.min)
        local target_value = 0.0
        if denom ~= 0 then
            target_value = math.max(0.0, math.min(1.0, (opts.value - opts.min) / denom))
        end
        state.value = ui_anim_step(state.value, target_value, opts.value_speed or 7.0)

        local pad_x = 8
        local track_h = math.max(4, math.floor(height * 0.18))
        local track_y = draw_min.y + math.floor((height - track_h) * 0.5)
        local track_x1 = draw_min.x + pad_x
        local track_x2 = draw_max.x - pad_x
        local track_w = math.max(1, track_x2 - track_x1)
        local knob_x = track_x1 + track_w * state.value
        local knob_y = track_y + track_h * 0.5
        local knob_r = math.max(5.0, math.min(6.6, height * 0.22 + state.hover * 0.6 + state.active * 0.9))

        draw_list:AddRectFilled(
            iv2(track_x1, track_y),
            iv2(track_x2, track_y + track_h),
            ui_control_color(1.0, 1.0, 1.0, 0.14 * alpha_mul),
            track_h * 0.5
        )
        if knob_x > track_x1 then
            draw_list:AddRectFilled(
                iv2(track_x1, track_y),
                iv2(knob_x, track_y + track_h),
                ui_control_color(1.0, 1.0, 1.0, (0.28 + state.active * 0.08) * alpha_mul),
                track_h * 0.5
            )
        end
        if draw_list.AddCircleFilled then
            draw_list:AddCircleFilled(
                iv2(knob_x, knob_y),
                knob_r,
                ui_control_color(1.0, 1.0, 1.0, (0.76 + state.hover * 0.10 + state.active * 0.12) * alpha_mul),
                24
            )
        end
        if draw_list.AddCircle then
            draw_list:AddCircle(
                iv2(knob_x, knob_y),
                knob_r,
                ui_control_color(1.0, 1.0, 1.0, (0.18 + state.active * 0.10) * alpha_mul),
                24,
                1.0
            )
        end

        local value_text = opts.display_value or ui_format_slider_value(opts.value)
        if value_text ~= nil and value_text ~= "" and imgui.CalcTextSize then
            local ok_size, value_size = pcall(function()
                return imgui.CalcTextSize(value_text)
            end)
            if ok_size and value_size then
                local text_x = math.max(track_x1, math.min(track_x2 - value_size.x, knob_x - value_size.x * 0.5))
                local text_y = track_y - value_size.y - 7
                draw_list:AddText(
                    iv2(text_x, text_y),
                    ui_control_color(1.0, 1.0, 1.0, (0.92 + state.hover * 0.04 + state.active * 0.06) * alpha_mul),
                    value_text
                )
            end
        end
    elseif opts.kind == "input" or opts.kind == "combo" then
        local frame_alpha = (0.04 + state.hover * 0.03 + state.active * 0.05) * alpha_mul
        local line_strength = (0.10 + state.hover * 0.06 + state.active * 0.12) * alpha_mul
        draw_list:AddRectFilled(
            iv2(draw_min.x + 1, draw_min.y + 1),
            iv2(draw_max.x - 1, draw_max.y - 1),
            ui_control_color(1.0, 1.0, 1.0, frame_alpha),
            radius
        )
        draw_list:AddRect(
            iv2(draw_min.x + 1, draw_min.y + 1),
            iv2(draw_max.x - 1, draw_max.y - 1),
            ui_control_color(1.0, 1.0, 1.0, line_strength * 0.55),
            radius,
            0,
            1.0
        )
        draw_list:AddRectFilled(
            iv2(draw_min.x + 6, draw_max.y - 2),
            iv2(draw_max.x - 6, draw_max.y - 1),
            ui_control_color(1.0, 1.0, 1.0, line_strength),
            1
        )
    elseif opts.kind == "collapsing" then
        local left_alpha = (0.10 + state.hover * 0.05 + state.open * 0.18) * alpha_mul
        draw_list:AddRectFilled(
            iv2(draw_min.x + 2, draw_min.y + 3),
            iv2(draw_min.x + 4, draw_max.y - 3),
            ui_control_color(1.0, 1.0, 1.0, left_alpha),
            1
        )
    end

    return state
end

local function ui_visible_label(label)
    local text = tostring(label or "")
    return text:gsub("##.*$", "")
end

function ui_format_slider_value(value)
    if value == nil then return "" end
    if math.type and math.type(value) == "integer" then
        return tostring(value)
    end
    if type(value) == "number" then
        if value == math.floor(value) then
            return tostring(math.floor(value))
        end
        local rounded = string.format("%.2f", value)
        rounded = rounded:gsub("(%..-)0+$", "%1")
        rounded = rounded:gsub("%.$", "")
        return rounded
    end
    return tostring(value)
end

function ui_smooth_input_text(label, buffer, buffer_size, flags)
    local pushed = ui_push_transparent_frame_style("input")
    local changed = imgui.InputText(label, buffer, buffer_size, flags or 0)
    ui_pop_transparent_frame_style(pushed)
    ui_draw_control_feedback("input", tostring(label), {kind = "input", rounding = 4})
    return changed
end

function ui_smooth_slider_int(label, value, min_value, max_value)
    local display_label = ui_visible_label(label)
    local internal_label = "##smooth_slider_int_" .. tostring(label)

    imgui.PushStyleColor(imgui.Col.Text, iv4(1.0, 1.0, 1.0, 0.0))
    local pushed = ui_push_transparent_frame_style("slider")
    local changed = imgui.SliderInt(internal_label, value, min_value, max_value)
    ui_pop_transparent_frame_style(pushed)
    imgui.PopStyleColor(1)

    ui_draw_control_feedback("slider", "int::" .. tostring(label), {
        kind = "slider",
        label = nil,
        value = value[0],
        display_value = ui_format_slider_value(value[0]),
        min = min_value,
        max = max_value,
        rounding = 4
    })

    if display_label ~= "" then
        imgui.SameLine(0, 10)
        imgui.AlignTextToFramePadding()
        imgui.Text(display_label)
    end
    return changed
end

function ui_smooth_slider_float(label, value, min_value, max_value)
    local display_label = ui_visible_label(label)
    local internal_label = "##smooth_slider_float_" .. tostring(label)

    imgui.PushStyleColor(imgui.Col.Text, iv4(1.0, 1.0, 1.0, 0.0))
    local pushed = ui_push_transparent_frame_style("slider")
    local changed = imgui.SliderFloat(internal_label, value, min_value, max_value)
    ui_pop_transparent_frame_style(pushed)
    imgui.PopStyleColor(1)

    ui_draw_control_feedback("slider", "float::" .. tostring(label), {
        kind = "slider",
        label = nil,
        value = value[0],
        display_value = ui_format_slider_value(value[0]),
        min = min_value,
        max = max_value,
        rounding = 4
    })

    if display_label ~= "" then
        imgui.SameLine(0, 10)
        imgui.AlignTextToFramePadding()
        imgui.Text(display_label)
    end
    return changed
end

function ui_smooth_combo(label, current_item, items, items_count)
    local pushed = ui_push_transparent_frame_style("combo")
    local changed = imgui.Combo(label, current_item, items, items_count)
    ui_pop_transparent_frame_style(pushed)
    ui_draw_control_feedback("combo", tostring(label), {kind = "combo", rounding = 4})
    return changed
end

function ui_minimal_checkbox(str_id, bool)
    elements.custom.checkbox = elements.custom.checkbox or {}

    local id = tostring(str_id or "")
    local display_label = id:gsub("##.*$", ""):gsub("^%s+", "")
    local storage = elements.custom.checkbox[id]
    if storage == nil then
        storage = {
            progress = bool[0] and 1.0 or 0.0,
            hover = 0.0
        }
        elements.custom.checkbox[id] = storage
    end

    local label_size = imgui.CalcTextSize(display_label ~= "" and display_label or " ")
    local circle_size = math.floor(label_size.y + 4)
    local height = math.max(circle_size, label_size.y) + 4
    local width = circle_size + (display_label ~= "" and (8 + label_size.x) or 0)

    local pos = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##minimal_checkbox_" .. id, iv2(width, height))
    local hovered = imgui.IsItemHovered()

    if clicked then
        bool[0] = not bool[0]
    end

    local dt = imgui.GetIO().DeltaTime
    if dt <= 0 then dt = 1 / 60 end
    dt = math.min(dt, 1 / 30)

    local target = bool[0] and 1.0 or 0.0
    storage.progress = storage.progress + (target - storage.progress) * math.min(dt * 16.0, 1.0)
    storage.hover = storage.hover + (((hovered and 1.0 or 0.0) - storage.hover) * math.min(dt * 20.0, 1.0))

    local alpha_mul = ui_effective_alpha()
    local draw_list = imgui.GetWindowDrawList()
    local circle_min = iv2(pos.x, pos.y + math.floor((height - circle_size) * 0.5))
    local center = iv2(circle_min.x + circle_size * 0.5, circle_min.y + circle_size * 0.5)
    local radius = math.max(4.0, circle_size * 0.42)

    local base_mix = 0.16 + storage.hover * 0.04 + storage.progress * 0.08
    local ring_alpha = (0.78 + storage.hover * 0.08) * alpha_mul
    local glow_alpha = (0.04 + storage.progress * 0.10) * alpha_mul

    draw_list:AddCircleFilled(center, radius, conv_c(iv4(base_mix, base_mix, base_mix, ring_alpha)), 24)

    if glow_alpha > 0.001 then
        draw_list:AddCircleFilled(
            center,
            math.max(1.0, radius - 1.0),
            conv_c(iv4(0.92, 0.92, 0.92, glow_alpha)),
            24
        )
    end

    if storage.progress > 0.001 then
        draw_minimal_checkbox_mark(
            draw_list,
            center,
            radius,
            storage.progress,
            conv_c(iv4(1.0, 1.0, 1.0, (0.26 + storage.progress * 0.74) * alpha_mul))
        )
    end

    if display_label ~= "" then
        local text_strength = math.min(1.0, 0.78 + storage.hover * 0.08 + storage.progress * 0.12)
        local text_pos = iv2(pos.x + circle_size + 8, pos.y + math.floor((height - label_size.y) * 0.5) - 1)
        draw_list:AddText(text_pos, conv_c(iv4(text_strength, text_strength, text_strength, alpha_mul)), display_label)
    end

    return clicked
end

