        odejda_prev_enable_jump = nil
    end
    if odejda_prev_enable_random_turns ~= nil then
        cVARS.enable_random_turns[0] = odejda_prev_enable_random_turns
        odejda_prev_enable_random_turns = nil
    end
    odejda_buy_started_at = nil
    odejda_buy_enter_sent = false
end

function send_odejda_alt_press()
    local data = samp_create_sync_data('player')
    data.keysData = data.keysData + 1024
    data.send()
    if tp_press_virtual_key then
        tp_press_virtual_key(18)
    else
        lua_thread.create(function()
            setVirtualKeyDown(18, true)
            wait(60)
            setVirtualKeyDown(18, false)
        end)
    end
end

function write_audit_log(message)
    if not message then return end
    if not audit_log_path then
        audit_log_path = getWorkingDirectory() .. "\\config\\lesorub_flupiflufi.log"
    end
    local f = io.open(audit_log_path, "a+")
    if f then
        f:write(os.date("[%Y-%m-%d %H:%M:%S] ") .. tostring(message) .. "\n")
        f:close()
    end
end

function schedule_save_cfg(delay_seconds)
    config_dirty = true
    local delay = tonumber(delay_seconds) or config_save_interval
    if delay < 0 then delay = 0 end
    local due = os.clock() + delay
    if config_save_due_at == 0 or due < config_save_due_at then
        config_save_due_at = due
    end
end

function flush_save_cfg_if_needed(force)
    if not config_dirty then return false end
    if not force and os.clock() < config_save_due_at then return false end
    local ok, err = pcall(save_cfg)
    if ok then
        config_dirty = false
        config_save_due_at = 0
        return true
    end
    write_audit_log("save_cfg failed: " .. tostring(err))
    return false
end

function refresh_telegram_credentials()
    token = u8:decode(ffi.string(cVARS.telegram_token)):gsub("^%s+", ""):gsub("%s+$", "")
    chat_id = u8:decode(ffi.string(cVARS.telegram_chat_id)):gsub("^%s+", ""):gsub("%s+$", "")
end

function telegram_is_ready()
    refresh_telegram_credentials()
    return cVARS.telegram[0] and token ~= "" and chat_id ~= ""
end

function start_telegram_updates_if_ready(force_restart)
    local signature = tostring(cVARS.telegram[0]) .. "|" .. token .. "|" .. chat_id
    if force_restart then
        telegram_polling_serial = telegram_polling_serial + 1
        telegram_polling_active = false
    end
    if not telegram_is_ready() then
        telegram_last_signature = signature
        telegram_polling_active = false
        return false
    end
    if telegram_polling_active and telegram_last_signature == signature then
        return true
    end
    telegram_polling_serial = telegram_polling_serial + 1
    telegram_last_signature = signature
    telegram_polling_active = true
    getLastUpdate()
    lua_thread.create(get_telegram_updates, telegram_polling_serial)
    write_audit_log("telegram polling started")
    return true
end

function telegram_watchdog_tick()
    refresh_telegram_credentials()
    local signature = tostring(cVARS.telegram[0]) .. "|" .. token .. "|" .. chat_id
    if signature ~= telegram_last_signature then
        start_telegram_updates_if_ready(true)
    elseif cVARS.telegram[0] and not telegram_polling_active then
        start_telegram_updates_if_ready(false)
    end
end

function backup_broken_config(raw)
    local cfg_path = getWorkingDirectory() .. "\\config\\lesorub_flupiflufi.json"
    local stamp = os.date("%Y%m%d_%H%M%S")
    local backup_path = cfg_path .. ".broken_" .. stamp
    local f = io.open(backup_path, "w")
    if f then
        f:write(raw or "")
        f:close()
    end
end

function write_text_file_atomic(path, data)
    local tmp_path = tostring(path) .. '.tmp'
    local f = io.open(tmp_path, 'w')
    if not f then return false, 'tmp open failed' end
    f:write(data or '')
    f:close()
    os.remove(path)
    local ok, err = os.rename(tmp_path, path)
    if ok then return true end
    local fallback = io.open(path, 'w')
    if not fallback then return false, err or 'rename failed' end
    fallback:write(data or '')
    fallback:close()
    os.remove(tmp_path)
    return true
end

function telegram_authorized_chat_id()
    refresh_telegram_credentials()
    return tostring(chat_id or config.telegram_chat_id or '')
end

function telegram_is_authorized_chat(test_chat_id)
    local incoming = tostring(test_chat_id or '')
    if incoming == '' then return false end
    if not cVARS.telegram_allow_only_saved_chat[0] then
        return true
    end
    local allowed = telegram_authorized_chat_id()
    return allowed ~= '' and incoming == allowed
end

function telegram_is_action_allowed(action_name)
    if action_name == 'exit' then
        return cVARS.telegram_allow_exit[0]
    elseif action_name == 'crash' then
        return cVARS.telegram_allow_crash[0]
    elseif action_name == 'chat_send' then
        return cVARS.telegram_allow_chat_send[0]
    end
    return true
end

action_queue = {}
action_queue_seq = 0

function enqueue_action(item)
    action_queue_seq = action_queue_seq + 1
    item.id = action_queue_seq
    item.created_at = os.clock()
    table.insert(action_queue, item)
    return item.id
end

function get_action_queue_length()
    return #action_queue
end

function queue_process_chat_command(cmd, internal_command, delay_seconds)
    cmd = tostring(cmd or '')
    if cmd == '' then return nil end
    return enqueue_action({kind = 'process_chat', cmd = cmd, internal_command = internal_command == true, due_at = os.clock() + (delay_seconds or 0)})
end

function queue_send_chat_message(msg, delay_seconds)
    msg = tostring(msg or '')
    if msg == '' then return nil end
    return enqueue_action({kind = 'send_chat', msg = msg, due_at = os.clock() + (delay_seconds or 0)})
end

function queue_virtual_key_tap(vk, hold_ms, delay_seconds)
    if not vk then return nil end
    return enqueue_action({kind = 'key_tap', vk = vk, hold = math.max(0.02, (tonumber(hold_ms) or 50) / 1000), stage = 0, due_at = os.clock() + (delay_seconds or 0)})
end

function process_action_queue_tick()
    local item = action_queue[1]
    if not item then return end
    local now = os.clock()
    if item.due_at and now < item.due_at then return end

    if item.kind == 'key_tap' then
        if item.stage == 0 then
            setVirtualKeyDown(item.vk, true)
            item.stage = 1
            item.due_at = now + item.hold
            return
        end
        setVirtualKeyDown(item.vk, false)
        table.remove(action_queue, 1)
        return
    elseif item.kind == 'process_chat' then
        tp_reconnect_state.internal_command = item.internal_command == true
        local ok = pcall(sampProcessChatInput, item.cmd)
        if not ok then
            pcall(sampSendChat, item.cmd)
        end
        tp_reconnect_state.internal_command = false
        table.remove(action_queue, 1)
        return
    elseif item.kind == 'send_chat' then
        pcall(sampSendChat, item.msg)
        table.remove(action_queue, 1)
        return
    end

    table.remove(action_queue, 1)
end

BOT_STATE_TIMEOUTS = {
    RUN_FIX_ZABOR = 60,
    SEARCH_TREE = 35,
    SCAN_FOR_TREE = 20,
    WAIT_ALT = 12,
    RUN_CENTER = 25,
    RUN_TO_POINT_3 = 25,
    RUN_SDACHA = 75,
    GO_KYSHAT = 60,
    RETURN_FROM_FOOD = 45,
    ODEJDA_DOLBAEB = 90,
    ESCAPE_VEHICLE = 20
}

bot_state_watch = {
    last = nil,
    entered_at = 0
}

function note_bot_state_change_tick()
    if bot_state_watch.last ~= bot_state then
        bot_state_watch.last = bot_state
        bot_state_watch.entered_at = os.clock()
    end
end

function get_bot_state_timeout_seconds(state_name)
    return BOT_STATE_TIMEOUTS[state_name]
end

function get_bot_state_timeout_remaining()
    local timeout = get_bot_state_timeout_seconds(bot_state)
    if not timeout or bot_state_watch.entered_at <= 0 then return nil end
    local remaining = timeout - (os.clock() - bot_state_watch.entered_at)
    if remaining < 0 then remaining = 0 end
    return remaining
end

function recover_bot_to_safe_state(reason, next_state)
    reason = tostring(reason or 'unknown')
    write_audit_log('state recover: ' .. reason .. ' | from=' .. tostring(bot_state))
    walking = false
    current_tree_target = nil
    set_wait_alt = 0
    state_entered["RUN_CENTER"] = false
    state_entered["RUN_TO_POINT_3"] = false
    state_entered["WAIT_ALT"] = false
    state_entered["ESCAPE_VEHICLE"] = false
    odejda_step = nil
    enable_jump = cVARS.enable_jump[0]
    enable_random_turns = cVARS.enable_random_turns[0]
    if next_state == false then
        cVARS.bot[0] = false
        bot_state = 'IDLE'
    else
        bot_state = next_state or 'RUN_FIX_ZABOR'
    end
end

function bot_state_watchdog_tick()
    if not cVARS.state_watchdog_enabled[0] then
        bot_state_watch.last = bot_state
        bot_state_watch.entered_at = os.clock()
        return
    end
    if not cVARS.bot[0] then
        bot_state_watch.last = bot_state
        bot_state_watch.entered_at = os.clock()
        return
    end
    note_bot_state_change_tick()
    local timeout = get_bot_state_timeout_seconds(bot_state)
    if not timeout or bot_state_watch.entered_at <= 0 then return end
    if (os.clock() - bot_state_watch.entered_at) >= timeout then
        recover_bot_to_safe_state('watchdog timeout', 'RUN_FIX_ZABOR')
        bot_state_watch.last = bot_state
        bot_state_watch.entered_at = os.clock()
    end
end

function hardening_service_loop()
    while true do
        wait(100)
        process_action_queue_tick()
        bot_state_watchdog_tick()
    end
end

function sync_persistent_runtime_toggles()
    if config.bot_enabled ~= cVARS.bot[0]
    or config.runskincj ~= cVARS.runskincj[0]
    or config.auto_buy_chainsaw ~= cVARS.auto_buy_chainsaw[0]
    or config.collision_player ~= player[0]
    or config.collision_vehicle ~= vehicle[0]
    or config.collision_object ~= object[0]
    or config.collision_stumps ~= objectpen[0]
    or config.collision_keep_trees ~= objectnotree[0] then
        schedule_save_cfg()
    end
end

