function create_startup_objects_once()
    if startup_objects_created then return end
    startup_objects_created = true
    for _, data in ipairs(HARDENING_STARTUP_OBJECTS) do
        local obj = createObject(data[1], data[2], data[3], data[4])
        setObjectCoordinates(obj, data[2], data[3], data[4])
        setObjectRotation(obj, data[5], data[6], data[7])
    end
end

function register_main_chat_commands()
    sampRegisterChatCommand(config.menu_command, function()
        cVARS.menu[0] = not cVARS.menu[0]
        sampToggleCursor(cVARS.menu[0])
        if not cVARS.bot[0] then bot_state = "IDLE" end
    end)
    sampRegisterChatCommand(ffi.string(cVARS.bot_command), function()
        cVARS.bot[0] = not cVARS.bot[0]
        if cVARS.bot[0] then
            if cVARS.time_probe_enabled[0] then
                reset_time_probe_cycle()
            end
            if cVARS.random_inventory_enabled[0] then
                reset_random_inventory_cycle()
            end
        else
            bot_state = "IDLE"
            clear_time_probe_state()
            clear_random_inventory_state()
        end
    end)
end

function main_handle_runtime_toggles(cursor_visible)
    if cVARS.menu_hotkey[0] and isKeyJustPressed(cVARS.menu_hotkey[0]) then
        cVARS.menu[0] = not cVARS.menu[0]
    end
    if not changepos and cursor_visible ~= cVARS.menu[0] then
        sampToggleCursor(cVARS.menu[0])
        cursor_visible = cVARS.menu[0]
    end
    if cVARS.bot_hotkey[0] and isKeyJustPressed(cVARS.bot_hotkey[0]) then
        cVARS.bot[0] = not cVARS.bot[0]
        if cVARS.bot[0] then
            if cVARS.time_probe_enabled[0] then
                reset_time_probe_cycle()
            end
            if cVARS.random_inventory_enabled[0] then
                reset_random_inventory_cycle()
            end
        else
            bot_state = "IDLE"
            clear_time_probe_state()
            clear_random_inventory_state()
        end
        syncToggleButton(ti.ICON_TREES .. u8" Бот дерева", cVARS.bot[0])
    end
    sync_persistent_runtime_toggles()
    flush_save_cfg_if_needed(false)
    telegram_watchdog_tick()
    if audit_last_bot_enabled ~= cVARS.bot[0] then
        audit_last_bot_enabled = cVARS.bot[0]
        write_audit_log("bot_enabled=" .. tostring(cVARS.bot[0]))
    end
    if audit_last_bot_state ~= bot_state then
        audit_last_bot_state = bot_state
        write_audit_log("bot_state=" .. tostring(bot_state))
    end
    return cursor_visible
end

function main_handle_combo_menu_toggle()
    if cVARS.combo_key1[0] and cVARS.combo_key2[0] then
        if isKeyDown(cVARS.combo_key1[0]) and isKeyDown(cVARS.combo_key2[0]) then
            cVARS.menu[0] = not cVARS.menu[0]
            wait(200)
        end
    end
end

function tp_guard_connection_state()
    if (tp_state.active or tp_state.pending or tp_auto_state.armed or tp_auto_state.cleanup_active)
    and not (isSampAvailable() and sampGetGamestate() == 3)
    and not tp_state.connection_closed then
        tp_mark_connection_closed("отмена телепорта из-за закрытия соединения", not tp_is_manual_reconnect_pending())
        if tp_is_manual_reconnect_pending() then
            tp_note_reconnect_progress()
        end
    end
end

function main()
    math.randomseed(os.time())
    if not isSampfuncsLoaded() or not isSampLoaded() then return end
    while not isSampAvailable() do wait(100) end
    hwin = ffi.C.GetActiveWindow()
    cMsg("Успешно загружен! Используй {ABABAB}/sawbot")
    lua_thread.create(warning)
    lua_thread.create(warning2)
    load_cfg()
    refresh_telegram_credentials()
    start_telegram_updates_if_ready(false)
    if cVARS.time_probe_enabled[0] then
        reset_time_probe_cycle()
    end
    if cVARS.random_inventory_enabled[0] then
        reset_random_inventory_cycle()
    end
    lua_thread.create(hardening_service_loop)
    register_main_chat_commands()
    create_startup_objects_once()
    X,Y = getScreenResolution()    
    menu_cursor_visible = false
    while true do wait(0)
        menu_cursor_visible = main_handle_runtime_toggles(menu_cursor_visible)
        main_handle_combo_menu_toggle()
        gradient_offset = gradient_offset + 0.5
        if gradient_offset > 300 then gradient_offset = 0 end
        applyAnimationSpeed()
        if cVARS.infinite_run[0] then
            mem.setint8(0xB7CEE4, 1)
        else
            mem.setint8(0xB7CEE4, 0)
        end
        if not cVARS.bot[0] then
            walking = false
        end
        tp_guard_connection_state()
        spawn_ready = tp_is_spawn_ready()
        if spawn_ready and not tp_auto_state.last_spawned then
            tp_state.connection_closed = false
            tp_clear_manual_reconnect_request()
            tp_reset_reconnect()
            if cVARS.auto_teleport_enabled[0] then
                tp_begin_spawn_cleanup()
            else
                tp_reset_auto_schedule()
            end
        elseif not spawn_ready and tp_auto_state.last_spawned then
            tp_mark_connection_closed("отмена телепорта из-за закрытия соединения")
        end
        tp_auto_state.last_spawned = spawn_ready
        tp_process_auto_reconnect(spawn_ready)
        tp_handle_ui_guard()

        if tp_auto_state.cleanup_active then
            if not cVARS.auto_teleport_enabled[0] or not spawn_ready or tp_state.connection_closed then
                tp_reset_auto_schedule()
            else
                now = os.clock()
                quiet_enough = tp_auto_state.popup_seen and tp_auto_state.controllable and (now - tp_auto_state.last_activity_at) >= 1.0
                deadline_hit = now >= tp_auto_state.cleanup_deadline

                if quiet_enough or deadline_hit then
                    tp_finish_spawn_cleanup(true)
                end
            end
        elseif tp_auto_state.armed then
            if not cVARS.auto_teleport_enabled[0] then
                tp_reset_auto_schedule()
            elseif spawn_ready and not tp_state.active and not tp_state.pending and os.clock() >= tp_auto_state.trigger_at then
                tp_reset_auto_schedule()
                teleport_to_farm_job()
            end
        end
        if cVARS.autobeer[0] and cVARS.bot[0] then
            now = os.clock()
            if now - lastBeerTime >= 600 then
                lastBeerTime = now
                sampSendChat("/beer")
                sampAddChatMessage("{00FF00}[AutoBeer]{FFFFFF} Выпито пиво (интервал 10 минут)", -1)
            end
        end
        if cVARS.runskincj[0] then
            mem.setuint8(sampGetServerSettingsPtr(), 1)
        end
        if cVARS.stat_status[0] then
            zarabotok = cVARS.derevo_amount[0] * cVARS.derevo_value[0]
            r, g, b, a = rainbow(1, 255, 15)
            renderFontDrawText(font, (cVARS.bot[0] and 'Статус: Работает!' or 'Статус: Выкл')..'\nКол-во дерева: '..cVARS.derevo_amount[0]..' ('..zarabotok ..'$)', cVARS.x, cVARS.y, (cVARS.rainbowcolor[0] and join_argb(a, r, g, b) or -1))
        end
        if cVARS.time_probe_enabled[0] and cVARS.time_probe_show_remaining[0] then
            y_offset = cVARS.stat_status[0] and 35 or 0
            remaining = get_time_probe_remaining()
            renderFontDrawText(font, 'До /time: ' .. remaining .. ' сдач', cVARS.x, cVARS.y + y_offset, -1)
        end
        draw_random_inventory_countdown()
        if cVARS.antiadmin_skipdialog[0] then
            dialogskip = math.random(cVARS.antiadmin_skip11[0], cVARS.antiadmin_skip22[0])
        end
        if cVARS.tracers[0] then
            x, y, z = getCharCoordinates(PLAYER_PED)
			pX, pY = convert3DCoordsToScreen(x, y, z)
			for id = 0, 2048 do
				if sampIs3dTextDefined(id) then
					text, color, posX, posY, posZ, distance, ignore_walls, textPlayerId, veh = sampGet3dTextInfoById(id)
					distance = getDistanceBetweenCoords3d(posX, posY, posZ, x, y, z)
                    if text:find("Срубить дерево") and isPointOnScreen(posX,posY,posZ, -1) and distance < 60 then 
						wX, wY = convert3DCoordsToScreen(posX,posY,posZ)
						renderDrawLine(pX,pY,wX,wY, 1,0xFFFFFFFF)
                        renderDrawPolygon(wX,wY,5,5,16,0,0xFF00FFFF)
					end
				end
			end
        end
        if satiety and cVARS.autoeat[0] and satiety <= cVARS.eatpercent[0] then
            if cVARS.eatmethod[0] == 0 then
                wait(500)
                sampSendChat('/cheeps')
                wait(3500)
            elseif cVARS.eatmethod[0] == 1 then
                wait(500)
                sampSendChat('/jfish')
                wait(3500)
            elseif cVARS.eatmethod[0] == 2 then
                wait(500)
                sampSendChat('/jmeat')
                wait(3500)
            elseif cVARS.eatmethod[0] == 3 then
                wait(500)
                sampSendChat('/meatbag')
                wait(3500)
            end
        end
        if objectpen[0] then
            for k, v in ipairs(getAllObjects()) do
                if doesObjectExist(v) then
                    model = tostring(getObjectModel(v))
                    if model == "14872" then
                        if objectpen[0] then
                            setObjectCollision(v, not objectpen[0])
                            mad.set_object_model_alpha(v, mainIni.alpha.object)
                        end
                    end
                end
            end
        else
            for k, v in ipairs(getAllObjects()) do
                if doesObjectExist(v) then
                    mad.set_object_model_alpha(v, 250)
                end
            end
        end
        --колизия
        if object[0] then
            for k, v in ipairs(getAllObjects()) do
                if doesObjectExist(v) then
                    model = tostring(getObjectModel(v))

                    if model == "687" or model == "685" then
                        if objectnotree[0] then
                            setObjectCollision(v, true)
                            mad.set_object_model_alpha(v, 250)
                        end
                    elseif model == "3172" or model == "3171" or model == "3168" then
                        setObjectCollision(v, false)
                        mad.set_object_model_alpha(v, mainIni.alpha.object)
                    else
                        if #tostring(mainIni.delObject.blackList) == 0 then
                            if not findTable(tostring(mainIni.delObject.whiteList), model) then
                                setObjectCollision(v, false)
                                mad.set_object_model_alpha(v, mainIni.alpha.object)
                            end
                        else
                            for n in tostring(mainIni.delObject.blackList):gmatch("(%S+)") do
                                if model == n then
                                    setObjectCollision(v, false)
                                    mad.set_object_model_alpha(v, mainIni.alpha.object)
                                end
                            end
                        end
                    end
                end
            end
        else
            for k, v in ipairs(getAllObjects()) do
                if doesObjectExist(v) then
                    mad.set_object_model_alpha(v, 250)
                end
            end
        end
        if player[0] then
            for k, v in ipairs(getAllChars()) do
                if doesCharExist(v) and v ~= PLAYER_PED then
                    setCharCollision(v, not player[0])
                end
            end
        end
        if vehicle[0] then
            for k, v in ipairs(getAllVehicles()) do
                if doesVehicleExist(v) then
                    setCarCollision(v, not vehicle[0])
                end
            end     
        else
            for k, v in ipairs(getAllVehicles()) do
                if doesVehicleExist(v) then
                    setCarCollision(v, true)
                end
            end
        end
                
        --колизия
        if changepos then
            sampToggleCursor(true)
            x, y = getCursorPos()
            cVARS.x = x
            cVARS.y = y
            if isKeyJustPressed(0x01) then
               sampAddChatMessage('Позиция сохранена.', -1)
               changepos = false
               sampToggleCursor(false)
            end
         end

        if cVARS.bot[0] then
            f, tree = getNearestTree()
            if cVARS.time_probe_enabled[0] then
                ensure_time_probe_cycle()
            end
            if process_random_inventory() then
            elseif cVARS.time_probe_enabled[0] and time_probe_pending then
                walking = false
                setGameKeyState(1, 0)
                setGameKeyState(16, 0)
                if os.clock() >= time_probe_pause_until then
                    sampSendChat('/time')
                    time_probe_pending = false
                    pick_next_time_probe_target()
                end
            elseif bot_state == "IDLE" then
                bot_state = "RUN_FIX_ZABOR"
            elseif bot_state == "RUN_FIX_ZABOR" then
                point = fix_zabors[last_fix_zabor_id]
                selected_sdacha = nil
                runToPoint(point[1], point[2], point[3])
                local distance = distPoint(point[1], point[2], point[3])
                if distance < 5 then
                    bot_state = "SEARCH_TREE"
                    last_fix_zabor_id = math.random(1, #fix_zabors)
                end
            elseif bot_state == "SCAN_FOR_TREE" then
                f, tree = getNearestTree()
            
                if f then
                    bot_state = "SEARCH_TREE"
                else
                    if not current_cam_angle then current_cam_angle = 0.0 end
                    current_cam_angle = (current_cam_angle + 0.8) % 360
                    px, py, pz = getCharCoordinates(PLAYER_PED)
            
                    camX = px + math.cos(math.rad(current_cam_angle)) * cVARS.camera_dist[0]
                    camY = py + math.sin(math.rad(current_cam_angle)) * cVARS.camera_dist[0]
                    camZ = pz + cVARS.camera_height_offset[0]
            
                    set_camera_direction({camX, camY, camZ})
            
                    walking = false
                    setGameKeyState(1, 0)
                    setGameKeyState(16, 0)
                end   
            elseif bot_state == "RUN_CENTER" then
                if not state_entered["RUN_CENTER"] then
                    if cVARS.enable_random_pauses[0] then
                        wait(math.random(1000, 1500))
                    end
                    state_entered["RUN_CENTER"] = true
                end
                nearest_c = получитьПерпендикулярКЦентру()
                local center_r = получитьПерпендикулярКЦентру()
                pX, pY, pZ = getCharCoordinates(PLAYER_PED)
                local distance_to_center = getDistanceBetweenCoords2d(center_r[1], center_r[2], pX, pY)
                local res = lineVec({x = center_r[1], y = center_r[2]}, {x = точки_дАроги[2].x, y = точки_дАроги[2].y}, (10 - distance_to_center) > 0 and (5 + 10 - distance_to_center) or 5)
                runToPoint(res.x, res.y, nearest_c[3])
                local distance = distPoint(nearest_c[1], nearest_c[2], nearest_c[3])
                if distance < 5 then
                    bot_state = "RUN_SDACHA"
                    state_entered["RUN_SDACHA"] = false
                end
            elseif bot_state == "RUN_TO_POINT_3" then
                if not state_entered["RUN_TO_POINT_3"] then
                    if cVARS.enable_random_pauses[0] then
                        wait(math.random(1000, 1500))
                    end
                    state_entered["RUN_TO_POINT_3"] = true
                end
                if current_new_point_index <= #selected_new_points then
                    local point = selected_new_points[current_new_point_index]
                    runToPoint(point.x, point.y, point.z)
                    local distance = distPoint(point.x, point.y, point.z)
                    pX, pY, pZ = getCharCoordinates(PLAYER_PED)
                    if distance < 2.0 then
                        current_new_point_index = current_new_point_index + 1
                        if current_new_point_index > #selected_new_points then
                            selected_sdacha = sdacha_points[3]
                            bot_state = "RUN_SDACHA"
                            current_new_point_index = 1
                            selected_new_points = {}
                        end
                    end
                end
            elseif bot_state == "RUN_SDACHA" then
                local target_sdacha
                if cVARS.smart_sdacha[0] then
                    target_sdacha, _ = findNearestSdachaPoint()
                else
                    index = cVARS.selected_sdacha_index[0] + 1
                    target_sdacha = sdacha_points[index]
                end
                if not target_sdacha then
                    target_sdacha = sdacha_points[1]
                end
                runToPoint(target_sdacha.x, target_sdacha.y, target_sdacha.z)
                local distance = distPoint(target_sdacha.x, target_sdacha.y, target_sdacha.z)
                if distance < 1.5 then
                    walking = false
                    if last_alt then
                        local data = samp_create_sync_data('player')
                        data.keysData = data.keysData + (last_alt and 1024 or 0)
                        data.send()
                    end
                    last_alt = not last_alt
                end
            elseif bot_state == "GO_KYSHAT" then
                runToPoint(-537.37, -193.53, 79.52)
                local distance = distPoint(-537.37, -193.53, 79.52)
                if distance < 1.5 and active then
                    wait(1000)
                    sendCustomPacket('streetFood.purchase|pizza')
                    wait(1000)
                    sendCustomPacket('streetFood.purchase|hotdog')
                    sendCustomPacket('streetFood.close')
                    active = false
                    bot_state = "RETURN_FROM_FOOD"
                end
            elseif bot_state == "RETURN_FROM_FOOD" then
                runToPoint(-518.3679, -185.5178, 78.0082)
                local return_distance = distPoint(-518.3679, -185.5178, 78.0082)
                if return_distance < 1.5 then
                    bot_state = "RUN_FIX_ZABOR"
                end
            elseif bot_state == "SEARCH_TREE" then
                f, tree = getNearestTree()

                if f then
                    set_current_tree_target(tree)
                    runToPoint(current_tree_target.x, current_tree_target.y, current_tree_target.z)
                    if distPoint(current_tree_target.x, current_tree_target.y, current_tree_target.z) < 1.5 then
                        bot_state = "WAIT_ALT"
                        set_wait_alt = os.clock()
                        state_entered["WAIT_ALT"] = false
                    end
                else
                    set_current_tree_target(nil)
                    bot_state = "SCAN_FOR_TREE"
                end
            elseif bot_state == "WAIT_ALT" then
                if not current_tree_target then
                    bot_state = "SEARCH_TREE"
                else
                    tx, ty, tz = current_tree_target.x, current_tree_target.y, current_tree_target.z
                    mX, mY, mZ = getCharCoordinates(PLAYER_PED)
                    local distance2d = getDistanceBetweenCoords2d(mX, mY, tx, ty)
                    if os.clock() - set_wait_alt > 15 then
                        table.insert(ignore_trees, {tx, ty, tz}) -- баним точку нахуй, если она сломана
                        current_tree_target = nil
                        bot_state = "SEARCH_TREE"
                    elseif distance2d > 1.5 then
                        bot_state = "SEARCH_TREE" -- если испарилось дерево нахуй блять
                    else
                        local distance3d = getDistanceBetweenCoords3d(mX, mY, mZ, tx, ty, tz)
                        walking = false
                        setGameKeyState(1,0)
                        setGameKeyState(16, distance3d <= 8 and 0 or 1)
                        if last_alt then 
                            local data = samp_create_sync_data('player')
                            data.keysData = data.keysData + (last_alt and 1024 or 0)
                            data.send()
                        end
                        last_alt = not last_alt -- вроде это не надо, ибо обычная синхра сама отправляет и тоже самое сделает
                    end
                end
            elseif bot_state == "ESCAPE_VEHICLE" then
                if not state_entered["ESCAPE_VEHICLE"] then
                    state_entered["ESCAPE_VEHICLE"] = true
                end
                runToPoint(safe_point_away.x, safe_point_away.y, safe_point_away.z)

                local distance = distPoint(safe_point_away.x, safe_point_away.y, safe_point_away.z)
                if distance < 3.0 then
                    cVARS.bot[0] = false
                    bot_state = "IDLE"
                    if cVARS.telegram[0] then
                        sendTelegramNotification("Достигнута безопасная точка. Бот выключен.")
                    end
                end
            elseif bot_state == "ODEJDA_DOLBAEB" then
                if not odejda_step then odejda_step = 1 end
                if odejda_prev_enable_jump == nil then
                    odejda_prev_enable_jump = cVARS.enable_jump[0]
                end
                if odejda_prev_enable_random_turns == nil then
                    odejda_prev_enable_random_turns = cVARS.enable_random_turns[0]
                end
                cVARS.enable_jump[0] = false
                cVARS.enable_random_turns[0] = false
                if odejda_step == 1 then
                    runToPoint(-518.6240, -167.9373, 76.0160)
                    if distPoint(-518.6240, -167.9373, 76.0160) < 1.0 then
                        odejda_step = 2
                    end
                elseif odejda_step == 2 then
                    runToPoint(-520.0246, -173.7267, 76.9578)
                    if distPoint(-520.0246, -173.7267, 76.9578) < 1.0 then
                        odejda_step = 3
                    end
                elseif odejda_step == 3 then
                    runToPoint(-554.4147, -173.4129, 78.4309)
                    if distPoint(-554.4147, -173.4129, 78.4309) < 1.0 then
                        walking = false
                        if last_alt then
                            local data = samp_create_sync_data('player')
                            data.keysData = data.keysData + (last_alt and 1024 or 0)
                            data.send()
                        end
                        last_alt = not last_alt
                    end
                elseif odejda_step == 4 then
                    runToPoint(-534.1934, -172.6320, 78.4309)
                    if distPoint(-534.1934, -172.6320, 78.4309) < 1.0 then
                        odejda_step = 5
                    end
                elseif odejda_step == 5 then
                    runToPoint(-534.8281, -175.8239, 78.4309)
                    if distPoint(-534.8281, -175.8239, 78.4309) < 1.0 then
                        walking = false
                        if last_alt then
                            local data = samp_create_sync_data('player')
                            data.keysData = data.keysData + (last_alt and 1024 or 0)
                            data.send()
                        end
                        last_alt = not last_alt
                    end
                elseif odejda_step == 6 then
                    runToPoint(-521.8475, -172.5850, 77.4835)
                    if distPoint(-521.8475, -172.5850, 77.4835) < 1.0 then
                        if cVARS.auto_buy_chainsaw[0] then
                            odejda_step = 7
                            odejda_buy_started_at = nil
                            odejda_buy_enter_sent = false
                        else
                            bot_state = "RUN_FIX_ZABOR"
                            odejda_step = nil
                            restore_odejda_movement_settings()
                        end
                    end
                elseif odejda_step == 7 then
                    runToPoint(auto_buy_chainsaw_point.x, auto_buy_chainsaw_point.y, auto_buy_chainsaw_point.z)
                    if distPoint(auto_buy_chainsaw_point.x, auto_buy_chainsaw_point.y, auto_buy_chainsaw_point.z) < 1.0 then
                        walking = false
                        setGameKeyState(1, 0)
                        setGameKeyState(16, 0)
                        if not odejda_buy_started_at then
                            odejda_buy_started_at = os.clock()
                            send_odejda_alt_press()
                        elseif not odejda_buy_enter_sent and os.clock() - odejda_buy_started_at >= 0.35 then
                            odejda_buy_enter_sent = true
                            if tp_press_virtual_key then
                                tp_press_virtual_key(13)
                            else
                                lua_thread.create(function()
                                    setVirtualKeyDown(13, true)
                                    wait(60)
                                    setVirtualKeyDown(13, false)
                                end)
                            end
                        elseif odejda_buy_enter_sent and os.clock() - odejda_buy_started_at >= 0.8 then
                            bot_state = "RUN_FIX_ZABOR"
                            odejda_step = nil
                            restore_odejda_movement_settings()
                        end
                    end
                end
            end
        end
    end
end

function rainbow(speed, alpha, offset)
    local clock = os.clock() + offset
    local r = math.floor(math.sin(clock * speed) * 127 + 128)
    local g = math.floor(math.sin(clock * speed + 2) * 127 + 128)
    local b = math.floor(math.sin(clock * speed + 4) * 127 + 128)
    return r,g,b,alpha
end

 function join_argb(a, r, g, b)
    local argb = b
    argb = bit.bor(argb, bit.lshift(g, 8))
    argb = bit.bor(argb, bit.lshift(r, 16))
    argb = bit.bor(argb, bit.lshift(a, 24))
    return argb
end

function перпендикуляторКПрямойЧерезТочку(точка_прямой_адин, точка_прямой_два, наша_точка)
    local икс = (точка_прямой_адин.x * точка_прямой_адин.x * наша_точка.x - 2 * точка_прямой_адин.x * точка_прямой_два.x * наша_точка.x + точка_прямой_два.x * точка_прямой_два.x * наша_точка.x + точка_прямой_два.x *
    (точка_прямой_адин.y - точка_прямой_два.y) * (точка_прямой_адин.y - наша_точка.y) - точка_прямой_адин.x * (точка_прямой_адин.y - точка_прямой_два.y) * (точка_прямой_два.y - наша_точка.y)) / ((точка_прямой_адин.x - точка_прямой_два.x) *
            (точка_прямой_адин.x - точка_прямой_два.x) + (точка_прямой_адин.y - точка_прямой_два.y) * (точка_прямой_адин.y - точка_прямой_два.y))
    local игрек = (точка_прямой_два.x * точка_прямой_два.x * точка_прямой_адин.y + точка_прямой_адин.x * точка_прямой_адин.x * точка_прямой_два.y + точка_прямой_два.x * наша_точка.x * (точка_прямой_два.y - точка_прямой_адин.y) - точка_прямой_адин.x *
    (наша_точка.x * (точка_прямой_два.y - точка_прямой_адин.y) + точка_прямой_два.x * (точка_прямой_адин.y + точка_прямой_два.y)) + (точка_прямой_адин.y - точка_прямой_два.y) * (точка_прямой_адин.y - точка_прямой_два.y) * наша_точка.y) / ((
                точка_прямой_адин.x - точка_прямой_два.x) * (точка_прямой_адин.x - точка_прямой_два.x) + (точка_прямой_адин.y - точка_прямой_два.y) * (точка_прямой_адин.y - точка_прямой_два.y));
    return {икс, игрек}
end

function получитьПерпендикулярКЦентру()
    mX, mY, mZ = getCharCoordinates(PLAYER_PED)
    local РеЗуЛьТаТ = перпендикуляторКПрямойЧерезТочку(точки_дАроги[1], точки_дАроги[2], {x = mX, y = mY})
    return {РеЗуЛьТаТ[1], РеЗуЛьТаТ[2], mZ}
end

function distPoint(x, y, z)
    mX, mY, mZ = getCharCoordinates(PLAYER_PED)
    local distance = getDistanceBetweenCoords3d(mX, mY, mZ, x, y, z)
    return distance
end

function runToPoint(x, y, z)
    now = os.clock()
    mX, mY, mZ = getCharCoordinates(PLAYER_PED)
    if now - last_check_time >= CHECK_INTERVAL then
        local moved = getDistanceBetweenCoords3d(mX, mY, mZ, last_pos_x, last_pos_y, last_pos_z)
        if moved < MIN_MOVE_DIST then
            stuck_ticks = stuck_ticks + 1
        else
            stuck_ticks = 0
        end
        last_pos_x, last_pos_y, last_pos_z = mX, mY, mZ
        last_check_time = now
        if cVARS.check_stuck[0] then
            if stuck_ticks >= STUCK_THRESHOLD and now - last_stuck_action_time >= STUCK_ACTION_COOLDOWN then
                cMsg(string.format("Застревание! (%.2f м за %.1fс)", moved, CHECK_INTERVAL))
                setGameKeyState(14, 255)
                setGameKeyState(0, math.random() > 0.5 and 220 or -220)
                wait(180)
                setGameKeyState(14, 0)
                setGameKeyState(0, 0)
                sendTelegramNotification("Бот растрял помоему")
                last_stuck_action_time = now
                stuck_ticks = stuck_ticks - 2
            end
        end
    end
    if cVARS.bot[0] and bot_state ~= "WAIT_TELEGA" and isCurrentCharWeapon(PLAYER_PED, 9) then
        setCurrentCharWeapon(PLAYER_PED, 0)
        cMsg("Убираем пилу с рук")
        wait(1000)
    end
    if not current_cam_angle then current_cam_angle = 0.0 end
    if not turn_state then
        turn_state = { dir=0, intensity=0.0, untilTime=0.0, lastChange=0.0 }
    end
    if not last_jump then last_jump = 0 end
    dx, dy = x - mX, y - mY
    local distance = getDistanceBetweenCoords3d(mX, mY, mZ, x, y, z)
    local target_angle = math.deg(math.atan2(dy, dx))
    local angle_diff = (target_angle - current_cam_angle + 180) % 360 - 180

    local smooth_factor
    if distance < 8 then
        smooth_factor = cVARS.camera_smooth_close[0]
    elseif distance < 25 then
        smooth_factor = cVARS.camera_smooth_mid[0]
    else
        smooth_factor = cVARS.camera_smooth_far[0]
    end
    current_cam_angle = current_cam_angle + angle_diff * smooth_factor
    current_cam_angle = (current_cam_angle + 360) % 360
    local cam_dist = cVARS.camera_dist[0]
    local camX = mX + math.cos(math.rad(current_cam_angle)) * cam_dist
    local camY = mY + math.sin(math.rad(current_cam_angle)) * cam_dist
    local camZ = mZ + cVARS.camera_height_offset[0]
    set_camera_direction({camX, camY, camZ})
    walking = true
    setGameKeyState(1, -255)
    now = os.clock()
    if cVARS.enable_jump[0] and (bot_state == "SEARCH_TREE" or bot_state == "RUN_FIX_ZABOR") and distance > 15 and now - last_jump > 1 then
        setGameKeyState(16, 0)
        setGameKeyState(14, 255)
        last_jump = now
    else
        setGameKeyState(14, 0)
        if distance > 8 then
            local phase = math.floor(now * 45) % 5
            setGameKeyState(16, (phase < 4) and 255 or 0)
        else
            setGameKeyState(16, 0)
        end
    end
    if now > turn_state.untilTime and cVARS.enable_random_turns[0] and now - turn_state.lastChange > 0.6 then
        local r = math.random()
        if r > 0.997 then
            turn_state.dir = 1
            turn_state.untilTime = now + (0.15 + math.random() * 0.5)
            turn_state.lastChange = now
        elseif r < 0.003 then
            turn_state.dir = -1
            turn_state.untilTime = now + (0.15 + math.random() * 0.5)
            turn_state.lastChange = now
        else
            turn_state.dir = 0
        end
    end
    local desired = 0
    if turn_state.dir == 1 then desired = 200
    elseif turn_state.dir == -1 then desired = -200
    end

    local inertia = 0.15
    turn_state.intensity = turn_state.intensity + (desired - turn_state.intensity) * inertia

    if distance < 2.0 then
        turn_state.intensity = turn_state.intensity * 0.25
    end

    local finalTurn = math.floor(turn_state.intensity)

    if isBuildingInFront() then
        finalTurn = -255
    end
    setGameKeyState(0, finalTurn)
end

function isBuildingInFront()
    if bot_state == "ESCAPE_VEHICLE" then
        return false
    end

    pX, pY, pZ = getCharCoordinates(PLAYER_PED)
    local ped_angle = math.rad(getCharHeading(PLAYER_PED)) + math.pi / 2
    ppX, ppY, ppZ = 5 * math.cos(ped_angle) + pX, 5 * math.sin(ped_angle) + pY, pZ + 0.8
    local result, colPoint = processLineOfSight(
        pX, pY, pZ,
        ppX, ppY, ppZ,
        true, true, true, false, false, false, false, false
    )
    if not result then
        return false
    end
    local entityType = colPoint.entityType
    if entityType == 1 then
        return true
    end
    if entityType == 2 then
        if cVARS.anti_vehicle[0] then
            if bot_state == "RUN_SDACHA" then
                bot_state = "ESCAPE_VEHICLE"
                state_entered["ESCAPE_VEHICLE"] = false
            end
        end
        return true
    end
    return false
end

function isTreeInFov(treeX, treeY)
    px, py, pz = getCharCoordinates(PLAYER_PED)
    if not current_cam_angle then current_cam_angle = 0.0 end
    local dx, dy = treeX - px, treeY - py
    local distance = math.sqrt(dx*dx + dy*dy)

    local angleToTree = math.deg(math.atan2(dy, dx))
    local diff = (angleToTree - current_cam_angle + 180) % 360 - 180

    local fov
    if distance < 2.5 then
        fov = 160
    elseif distance < 6 then
        fov = 120
    elseif distance < 12 then
        fov = 90
    else
        fov = 70
    end

    return math.abs(diff) <= (fov * 0.5)
end

function getNearestTree()
    if not isSampfuncsLoaded() or not isSampLoaded() or not isSampAvailable() then
        return false, {0, 0, 0}
    end

    local nearest_dist = math.huge
    local nearest_tree = {0, 0, 0}
    mX, mY, mZ = getCharCoordinates(PLAYER_PED)
    local find = false

    for id = 0, 2048 do
        if sampIs3dTextDefined(id) then
            text, color, posX, posY, posZ = sampGet3dTextInfoById(id)
            if text and text:find("Срубить дерево") then
                local distance = getDistanceBetweenCoords3d(posX, posY, posZ, mX, mY, mZ)
                local fov_ok = true
                if cVARS.use_tree_fov[0] then
                    fov_ok = isTreeInFov(posX, posY)
                end
                if distance < nearest_dist
                    and fov_ok
                    and noPlayersAround({posX, posY, posZ})
                    and not coordsIn({posX, posY, posZ}, ignore_trees)
                then
                    find = true
                    nearest_dist = distance
                    nearest_tree = {posX, posY, posZ}
                end
            end
        end
    end
    return find, nearest_tree
end

function coordsIn(el, _table) -- проверяет не является ли точка одной из спика, с 'погрешностью' в 1 метр
    for _, v in pairs(_table) do
        local dist = getDistanceBetweenCoords2d(el[1], el[2], v[1], v[2])
        if dist < 1 then
            return true
        end
    end
    return false
end

function noPlayersAround(point, radius) -- Проверка на свободу дерева, скорее всего можно было сделать через муновское inSphere или как-то так, но я пьяный наверное был когда писал
    local radius = radius or 3
    for _, player in ipairs(getAllChars()) do
        if select(1, sampGetPlayerIdByCharHandle(player)) and player ~= PLAYER_PED then
            plX, plY, plZ = getCharCoordinates(player)
            local dist = getDistanceBetweenCoords3d(plX, plY, plZ, point[1], point[2], point[3])
            if dist < radius then return false end
        end
    end
    return true
end

function set_camera_direction(point) -- украл откуда-то
	c_pos_x, c_pos_y, c_pos_z = getActiveCameraCoordinates()
	local vect = {x = point[1] - c_pos_x, y = point[2] - c_pos_y}
	local ax = math.atan2(vect.y, -vect.x)
	setCameraPositionUnfixed(0.0, -ax)
end

