function deletePreviousMessage(chat_id)
    if last_message_ids[chat_id] then
        async_http_request('https://api.telegram.org/bot' .. token .. '/deleteMessage?chat_id=' .. chat_id .. '&message_id=' .. last_message_ids[chat_id], '', function() end)
    end
end

function sendTelegramNotification(msg, target_chat_id)
    refresh_telegram_credentials()
    target_chat_id = target_chat_id or config.telegram_chat_id
    if not cVARS.telegram[0] or token == "" or not target_chat_id or tostring(target_chat_id) == "" then
        if not telegram_missing_warning_shown then
            telegram_missing_warning_shown = true
            write_audit_log("telegram notification skipped: token/chat_id missing")
        end
        return
    end
    telegram_missing_warning_shown = false
    msg = tostring(msg or ""):gsub('{......}', '')
    msg = encodeUrl(msg)
    local keyboard_json = encodeUrl(json.encode(getBackToMenuKeyboard()))
    deletePreviousMessage(target_chat_id)
    async_http_request('https://api.telegram.org/bot' .. token .. '/sendMessage?chat_id=' .. target_chat_id .. '&text=' .. msg .. '&reply_markup=' .. keyboard_json, '', function(result)
        local ok, proc_table = pcall(decodeJson, result or "")
        if ok and proc_table and proc_table.ok and proc_table.result.message_id then
            last_message_ids[target_chat_id] = proc_table.result.message_id
        end
    end)
end

function sendMenu(chat_id, text)
    local keyboard_json = encodeUrl(json.encode(getMainMenuKeyboard()))
    deletePreviousMessage(chat_id)
    async_http_request('https://api.telegram.org/bot' .. token .. '/sendMessage?chat_id=' .. chat_id .. '&text=' .. encodeUrl(text) .. '&reply_markup=' .. keyboard_json, '', function(result)
        local proc_table = decodeJson(result)
        if proc_table and proc_table.ok and proc_table.result.message_id then
            last_message_ids[chat_id] = proc_table.result.message_id
        end
    end)
end

function processing_telegram_updates(result)
    if result then
        local ok, proc_table = pcall(decodeJson, result or '')
        if ok and proc_table and proc_table.ok then
            for i, res in ipairs(proc_table.result) do
                if res.update_id > updateid then
                    updateid = res.update_id
                    local callback = res.callback_query
                    local message = res.message

                    if callback then
                        local chat_id = tostring(callback.message.chat.id)
                        if not telegram_is_authorized_chat(chat_id) then
                            write_audit_log('telegram ignored unauthorized callback chat_id=' .. chat_id)
                        else
                        local data = callback.data
                        if data == "start_bot" then
                            cVARS.bot[0] = true
                            bot_state = "RUN_FIX_ZABOR"
                            sendTelegramNotification("Бот лесоруба запущен!", chat_id)
                        elseif data == "stop_bot" then
                            cVARS.bot[0] = false
                            sendTelegramNotification("Бот лесоруба остановлен!", chat_id)
                        elseif data == "status" then
                            local statusText = "Статус бота: " .. (cVARS.bot[0] and "РАБОТАЕТ" or "ОСТАНОВЛЕН")
                            statusText = statusText .. "\nТекущее состояние: " .. bot_state
                            statusText = statusText .. "\nДеревьев срублено: " .. cVARS.derevo_amount[0]
                            sendTelegramNotification(statusText, chat_id)
                        elseif data == "earnings" then
                            local zarabotok = cVARS.derevo_amount[0] * cVARS.derevo_value[0]
                            local earningsText = "Текущий заработок: " .. zarabotok .. "$\nЦена за дерево: " .. cVARS.derevo_value[0] .. "$\nДеревьев срублено: " .. cVARS.derevo_amount[0]
                            sendTelegramNotification(earningsText, chat_id)
                        elseif data == "send_msg" then
                            sendTelegramNotification("Введите сообщение через !send <текст> в чат", chat_id)
                        elseif data == "exit_game" then
                            if telegram_is_action_allowed('exit') then
                                queue_process_chat_command('/q', false, 0)
                                sendTelegramNotification("Выхожу из игры!", chat_id)
                            else
                                sendTelegramNotification('Telegram /q disabled in settings.', chat_id)
                            end
                        elseif data == "close_dialog" then
                            queue_virtual_key_tap(27, 50, 0.5)
                            sendTelegramNotification("Диалог закрыт!", chat_id)
                        elseif data == "crash_game" then
                            if telegram_is_action_allowed('crash') then
                                piska = true
                                sendTelegramNotification("Игра крашнута!", chat_id)
                            else
                                sendTelegramNotification('Telegram crash disabled in settings.', chat_id)
                            end
                        elseif data == "make_screenshot" then
                            cumshot = true
                            queue_virtual_key_tap(119, 50, 1.0)
                            sendTelegramNotification("Скриншот делается, ожидается сохранение...",chat_id)                        
                        elseif data == "help" then
                            local helpText = "Команды бота:\n" ..
                                             "/start - Показать меню\n" ..
                                             "!send <текст> - Отправить сообщение в игровой чат\n" ..
                                             "Кнопки:\n" ..
                                             "Старт бота - Запустить бота\n" ..
                                             "Стоп бота - Остановить бота\n" ..
                                             "Статус - Показать статус бота\n" ..
                                             "Заработок - Показать заработок\n" ..
                                             "Отправить сообщение - Ввести сообщение для чата\n" ..
                                             "Выход из игры - Выйти из игры (/q)\n" ..
                                             "Закрыть диалог - Закрыть диалог (Esc)\n" ..
                                             "Краш игры - Крашнуть игру\n" ..
                                             "Сделать скриншот - Сделать и отправить скриншот\n" ..
                                             "Помощь - Показать это сообщение"
                            sendTelegramNotification(helpText, chat_id)
                        elseif data == "main_menu" then
                            sendMenu(chat_id, "Вы вернулись в меню. Выберите действие:")
                        end
                        end
                    elseif message and message.text then
                        local chat_id = tostring(message.chat.id)
                        if not telegram_is_authorized_chat(chat_id) then
                            write_audit_log('telegram ignored unauthorized message chat_id=' .. chat_id)
                        else
                        local text = u8:decode(message.text)
                        if text:match('^!send (.+)') then
                            local sendMessage = text:match('^!send (.+)')
                            if telegram_is_action_allowed('chat_send') then
                                if #sendMessage > 120 then
                                    sendMessage = sendMessage:sub(1, 120)
                                end
                                queue_send_chat_message(sendMessage, 0)
                                sendTelegramNotification("Сообщение отправлено в игровой чат: " .. sendMessage, chat_id)
                            else
                                sendTelegramNotification('Telegram chat send disabled in settings.', chat_id)
                            end
                        elseif text:match('^/start') then
                            sendMenu(chat_id, "Привет! Выберите действие бота:")
                        end
                        end
                    end
                end
            end
        end
    end
end

function get_telegram_updates(serial)
    while telegram_polling_active and telegram_polling_serial == serial and not updateid do wait(50) end
    local runner = requestRunner()
    local reject = function() end
    local args = ''
    while telegram_polling_active and telegram_polling_serial == serial do
        if telegram_is_ready() and updateid then
            local url = 'https://api.telegram.org/bot'..token..'/getUpdates?offset='..(updateid + 1)
            threadHandle(runner, url, args, function(result)
                processing_telegram_updates(result)
            end, reject)
        end
        wait(500)
    end
end

function getLastUpdate()
    if token == "" or chat_id == "" then return end
    async_http_request('https://api.telegram.org/bot' .. token .. '/getUpdates?chat_id=' .. chat_id .. '&offset=-1', '', function(result)
        if result then
            local proc_table = decodeJson(result)
            if proc_table and proc_table.ok then
                if #proc_table.result > 0 then
                    updateid = proc_table.result[1].update_id
                    if proc_table.result[1].message then
                        last_message_ids[chat_id] = proc_table.result[1].message.message_id
                    end
                else
                    updateid = 1
                end
            end
        end
    end)
end
