local function menu_style_vec(r, g, b, a)
    return iv4(r, g, b, (a or 1) * (ui_alpha_multiplier or 1.0) * (content_panel_alpha_multiplier or 1.0))
end

local function menu_draw_vec(r, g, b, a)
    return iv4(r, g, b, (a or 1) * (menu_draw_alpha_multiplier or 1.0))
end

function menu_priority_style_vec(r, g, b, a)
    return iv4(r, g, b, (a or 1) * (menu_priority_ui_alpha_multiplier or 1.0) * (content_panel_alpha_multiplier or 1.0))
end

function menu_collapsing_header(label)
    local state = ui_get_anim_state("collapsing", tostring(label), {hover = 0.0, active = 0.0, open = 0.0})
    local header_alpha = 0.70 + state.open * 0.10
    imgui.PushStyleColor(imgui.Col.Text, menu_priority_style_vec(1.0, 1.0, 1.0, 1.0))
    imgui.PushStyleColor(imgui.Col.Header, menu_priority_style_vec(0.10, 0.10, 0.10, header_alpha))
    imgui.PushStyleColor(imgui.Col.HeaderHovered, menu_priority_style_vec(0.16, 0.16, 0.16, 0.90))
    imgui.PushStyleColor(imgui.Col.HeaderActive, menu_priority_style_vec(0.22, 0.22, 0.22, 1.00))
    local opened = imgui.CollapsingHeader(label)
    local anim_state = ui_draw_control_feedback("collapsing", tostring(label), {kind = "collapsing", open = opened, rounding = 4, alpha = 0.95, open_speed = 8.0})
    imgui.PopStyleColor(4)
    return opened or (anim_state and anim_state.open and anim_state.open > 0.00005) or false
end

function menu_collapsing_header_begin(label)
    local visible = menu_collapsing_header(label)
    if visible then
        local state = ui_get_anim_state("collapsing", tostring(label), {open = 0.0, measured_height = 0.0})
        local alpha = math.max(0.0, math.min(1.0, state.open or 0.0))
        local eased_alpha = alpha * alpha * (3.0 - 2.0 * alpha)
        local height_alpha = math.max(0.0, math.min(1.0, (alpha - 0.12) / 0.88))
        height_alpha = height_alpha * height_alpha * (3.0 - 2.0 * height_alpha)
        if height_alpha <= 0.0005 then
            return false
        end

        local pushed = push_menu_style_alpha(eased_alpha)
        local prev_alpha = collapsible_content_alpha_multiplier or 1.0
        collapsible_content_alpha_multiplier = prev_alpha * eased_alpha

        local measured_height = state.measured_height or 0.0
        local child_height = math.max(1.0, measured_height * height_alpha)
        local child_flags = imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoBackground
        imgui.BeginChild("##collapse_body_" .. tostring(label), iv2(0, child_height), false, child_flags)

        elements.custom.collapsing_stack = elements.custom.collapsing_stack or {}
        table.insert(elements.custom.collapsing_stack, {
            pushed = pushed,
            label = tostring(label),
            prev_alpha = prev_alpha,
            eased_alpha = eased_alpha,
            height_alpha = height_alpha
        })
        return true
    end
    return false
end

function menu_collapsing_header_end()
    if elements.custom.collapsing_stack and #elements.custom.collapsing_stack > 0 then
        local info = table.remove(elements.custom.collapsing_stack)
        if info then
            local state = ui_get_anim_state("collapsing", info.label, {open = 0.0, measured_height = 0.0})
            local measured = imgui.GetCursorPosY()
            local style = imgui.GetStyle and imgui.GetStyle()
            local item_spacing_y = 0.0
            if style and style.ItemSpacing then
                item_spacing_y = style.ItemSpacing.y or 0.0
            end
            if measured and measured > 0 then
                local target_height = math.max(0.5, measured)
                if not state.measured_height or state.measured_height <= 0.0 then
                    state.measured_height = target_height
                else
                    state.measured_height = ui_anim_step(state.measured_height, target_height, 18.0)
                end
            end
            imgui.EndChild()
            if item_spacing_y > 0.0 and info.height_alpha and info.height_alpha < 0.999 then
                local cursor_y = imgui.GetCursorPosY()
                local smooth_gap = item_spacing_y * info.height_alpha
                local cut_gap = item_spacing_y - smooth_gap
                if cut_gap > 0.0 then
                    imgui.SetCursorPosY(math.max(0.0, cursor_y - cut_gap))
                end
            end
            collapsible_content_alpha_multiplier = info.prev_alpha or 1.0
            if info.pushed and info.pushed > 0 then
                imgui.PopStyleColor(info.pushed)
            end
        end
    end
end

function push_menu_style_alpha(alpha)
    local style = imgui.GetStyle and imgui.GetStyle()
    if not style or not style.Colors then return 0 end

    local pushed = 0
    for _, color_id in ipairs(menu_fade_color_ids) do
        local ok_read, color = pcall(function()
            return style.Colors[color_id]
        end)
        if ok_read and color then
            local ok_push = pcall(function()
                imgui.PushStyleColor(color_id, iv4(color.x, color.y, color.z, color.w * alpha))
            end)
            if ok_push then
                pushed = pushed + 1
            end
        end
    end

    return pushed
end

imgui.OnFrame(function() return cVARS.menu[0] or menu_anim_alpha > 0.001 end,
    function(self)
        local dt = imgui.GetIO().DeltaTime
        if dt <= 0 then dt = 1 / 60 end
        dt = math.min(dt, 1 / 60)

        local target_visible = cVARS.menu[0]
        if target_visible and not menu_anim_target_visible then
            menu_anim_alpha = 0.0
        end
        menu_anim_target_visible = target_visible

        if target_visible then
            menu_anim_alpha = math.min(menu_anim_alpha + dt / menu_anim_duration, 1.0)
        else
            menu_anim_alpha = math.max(menu_anim_alpha - dt / menu_anim_duration, 0.0)
            if menu_anim_alpha <= 0.0001 then
                menu_anim_alpha = 0.0
            end
        end

        menu_draw_alpha_multiplier = math.pow(menu_anim_alpha, 0.92)
        ui_alpha_multiplier = math.pow(menu_anim_alpha, 1.75)
        if menu_anim_alpha < 0.18 then
            ui_alpha_multiplier = ui_alpha_multiplier * (menu_anim_alpha / 0.18)
        end
        menu_priority_ui_alpha_multiplier = math.pow(menu_anim_alpha, 2.35)
        if menu_anim_alpha < 0.26 then
            menu_priority_ui_alpha_multiplier = menu_priority_ui_alpha_multiplier * (menu_anim_alpha / 0.26)
        end

        imgui.SetNextWindowSize(iv2(1100, 700), imgui.Cond.FirstUseEver)
        if cVARS.menu_movable[0] then
            local pos_x = cVARS.menu_pos_x[0]
            local pos_y = cVARS.menu_pos_y[0]
            if pos_x == 0 or pos_y == 0 then
                local scrW, scrH = getScreenResolution()
                pos_x = (scrW - 1100) / 2
                pos_y = (scrH - 700) / 2
            end
            local pos_cond = menu_anim_alpha < 0.999 and imgui.Cond.Always or imgui.Cond.Appearing
            imgui.SetNextWindowPos(iv2(pos_x, pos_y), pos_cond)
        else
            local scrW, scrH = getScreenResolution()
            imgui.SetNextWindowPos(iv2((scrW - 1100) / 2, (scrH - 700) / 2), imgui.Cond.Always)
        end

        local menu_style_push_count = push_menu_style_alpha(ui_alpha_multiplier)
        imgui.PushStyleColor(imgui.Col.WindowBg, iv4(0.0, 0.0, 0.0, 0.0))

        menu_window_open[0] = true
        imgui.Begin(u8"LesoРуб бот##main", menu_window_open, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
        local function menu_col(r, g, b, a)
            return conv_c(menu_draw_vec(r, g, b, a))
        end
        local dl = imgui.GetWindowDrawList()
        local win_pos = imgui.GetWindowPos()
        local win_size = imgui.GetWindowSize()
        local sidebar_width = 240
        local window_rounding = 8

        dl:AddRectFilled(iv2(win_pos.x, win_pos.y), iv2(win_pos.x + win_size.x, win_pos.y + win_size.y), menu_col(0.05, 0.05, 0.05, 1), window_rounding)
        dl:AddRectFilled(iv2(win_pos.x, win_pos.y), iv2(win_pos.x + sidebar_width, win_pos.y + win_size.y), menu_col(0.07, 0.07, 0.07, 1), window_rounding, imgui.DrawCornerFlags.Left)
        local title_text = u8"LesoРуб бот"
        local version_text = "v 1.8.1"
        local title_pos_y = win_pos.y + 20
        imgui.PushFont(fonts[28] or fonts[24] or fonts[20])
        local title_size = imgui.CalcTextSize(title_text)
        local title_pos_x = win_pos.x + 20
        local utf8_text = u8:decode(title_text)
        local full_text_width = title_size.x
        local current_x = title_pos_x
        local i = 1
        while i <= #utf8_text do
            local char_start = i
            local byte = utf8_text:byte(i)
            local char_len = 1
            if byte >= 240 then char_len = 4
            elseif byte >= 224 then char_len = 3
            elseif byte >= 192 then char_len = 2
            end
            local char = utf8_text:sub(char_start, char_start + char_len - 1)
            i = i + char_len
            local char_u8 = u8(char)
            local char_width = imgui.CalcTextSize(char_u8).x
            local char_center_x = current_x + char_width / 2
            local phase = (char_center_x - title_pos_x - gradient_offset * 1.2) % full_text_width
            local t = phase / full_text_width
            local gray = 0.2 + 0.8 * (math.sin(t * math.pi * 2) * 0.5 + 0.5)
            dl:AddText(iv2(current_x, title_pos_y), menu_col(gray, gray, gray, 1), char_u8)
            current_x = current_x + char_width
        end
        imgui.PopFont()
        dl:AddText(iv2(current_x + 10, title_pos_y), menu_col(0.6, 0.6, 0.6, 1), version_text)
        local line_y = win_pos.y + 70
        local line_start = win_pos.x + 20
        local line_end = win_pos.x + sidebar_width - 20
        local line_length = line_end - line_start
        local extended_length = line_length
        for i = 0, line_length, 2 do
            local phase = (i - gradient_offset * 1.5) % extended_length
            if phase < 0 then phase = phase + extended_length end
            local t = phase / extended_length
            local gray = 0.3 + 0.7 * (math.sin(t * math.pi * 4) * 0.5 + 0.5)
            dl:AddRectFilled(iv2(line_start + i, line_y), iv2(line_start + i + 2, line_y + 4), menu_col(gray, gray, gray, 1))
        end
        render_sidebar_navigation(dl, win_pos, sidebar_width, dt, menu_col)
        dl:AddLine(iv2(win_pos.x + 20, win_pos.y + win_size.y - 170), 
                iv2(win_pos.x + sidebar_width - 20, win_pos.y + win_size.y - 170), 
                menu_col(0.2, 0.2, 0.2, 1), 1)
        local block_padding_x = 20
        local block_padding_y = 15
        local block_x = win_pos.x + block_padding_x
        local block_y = win_pos.y + win_size.y - 155
        local block_width = sidebar_width - 40
        local block_height = 130
        dl:AddRectFilled(iv2(block_x, block_y), 
                        iv2(block_x + block_width, block_y + block_height), 
                        menu_col(0.07, 0.07, 0.07, 1), 4)
        dl:AddRect(iv2(block_x, block_y), 
                iv2(block_x + block_width, block_y + block_height), 
                menu_col(0.2, 0.8, 0.2, 1), 4, nil, 2)
        imgui.SetCursorPos(iv2(block_padding_x + 20, win_size.y - 150))
        imgui.PushFont(fonts[16])
        imgui.TextColored(menu_style_vec(0.3, 1.0, 0.3, 1), u8"cooming soon...")
        imgui.PopFont()
        local sub_line_y = block_y + 35
        local line_sub_start = block_x + 20
        local line_sub_length = block_width - 40
        for i = 0, line_sub_length, 2 do
            local phase = (i - gradient_offset * 1.3) % line_sub_length
            if phase < 0 then phase = phase + line_sub_length end
            local t = phase / line_sub_length
            local green = 0.4 + 0.6 * (math.sin(t * math.pi * 4) * 0.5 + 0.5)
            dl:AddRectFilled(
                iv2(line_sub_start + i, sub_line_y),
                iv2(line_sub_start + i + 2, sub_line_y + 3),
                menu_col(0.2, green, 0.2, 1)
            )
        end
        imgui.SetCursorPos(iv2(block_padding_x + 20, win_size.y - 110))
        imgui.Text(u8" ")
        imgui.SetCursorPos(iv2(block_padding_x + 20, win_size.y - 90))
        imgui.Text(u8" ")
        imgui.SetCursorPos(iv2(block_x - win_pos.x + 20, block_y - win_pos.y + 90))
        imgui.PushStyleColor(imgui.Col.Button,        menu_style_vec(0.15, 0.45, 0.15, 1))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, menu_style_vec(0.20, 0.60, 0.20, 1))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  menu_style_vec(0.25, 0.70, 0.25, 1))
        imgui.PushStyleColor(imgui.Col.Text,          menu_style_vec(1.0, 1.0, 1.0, 1))
        if imgui.Button(u8"cooming soon...", iv2(block_width - 40, 25)) then
            os.execute(' ')
        end
        imgui.PopStyleColor(4)
        content_alpha = update_content_transition(dt)
        local content_render_alpha = math.max(0.0, math.min(1.0, content_alpha))
        if not target_visible then
            content_render_alpha = content_render_alpha * math.max(0.0, math.min(1.0, menu_anim_alpha * 1.8))
        end
        render_tab = content_display_tab or selected_tab
        imgui.SetCursorPos(iv2(sidebar_width + 20, 30 + content_slide_offset * 0.2))
        imgui.PushFont(fonts[20] or fonts[16])
        imgui.TextColored(menu_style_vec(1.0, 1.0, 1.0, math.max(0.08, content_render_alpha)), render_tab)
        imgui.Separator()
        imgui.PopFont()
        imgui.SetCursorPos(iv2(sidebar_width + 20, 90 + content_slide_offset))
        content_panel_alpha_multiplier = content_render_alpha
        content_style_push_count = push_menu_style_alpha(content_render_alpha)
        imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0.0, 0.0, 0.0, 0.0))
        local draw_content_body = content_render_alpha > 0.06 and (target_visible or menu_anim_alpha > 0.48)
