function set_player_skin(id, skin)
	local BS = raknetNewBitStream()
	raknetBitStreamWriteInt32(BS, id)
	raknetBitStreamWriteInt32(BS, skin)
	raknetEmulRpcReceiveBitStream(153, BS)
	raknetDeleteBitStream(BS)
end

function pack_color(a, r, g, b)
    local color = b
    color = bit.bor(color, bit.lshift(g, 8))
    color = bit.bor(color, bit.lshift(r, 16))
    color = bit.bor(color, bit.lshift(a, 24))
    return color
end

function warning()
    while true do wait(0)
        if warn then
            local col = cVARS.warning_color
            local r, g, b, a = col[0]*255, col[1]*255, col[2]*255, col[3]*255
            local color1 = pack_color(a, r, g, b)
            local color2 = pack_color(a*0.2, r*0.2, g*0.2, b*0.2)

            for i = 1, 20 do
                renderDrawBox(0, 0, X, Y, (i % 2 == 0) and color1 or color2)
                wait(cVARS.antiadmin_flash[0] or 10)
            end

            warn = false
        end
    end
end

function warning2()
    while true do wait(0)
        if warn2 then
            local col = cVARS.warning_color
            local r, g, b, a = col[0]*255, col[1]*255, col[2]*255, col[3]*255
            local color1 = pack_color(a, r, g, b)
            local color2 = pack_color(a*0.2, r*0.2, g*0.2, b*0.2)

            for i = 1, 40 do
                renderDrawBox(0, 0, X, Y, (i % 2 == 0) and color1 or color2)
                wait(cVARS.antiadmin_flash[0] or 10)
            end

            warn2 = false
        end
    end
end


local function tp_clamp(value, min_value, max_value)
    if value < min_value then return min_value end
    if value > max_value then return max_value end
    return value
end

local function tp_lerp(a, b, t)
    return a + (b - a) * t
end

local function tp_chat(message)
    cMsg("{8ED6FF}[TP]{FFFFFF} " .. tostring(message))
end

tp_reset_reconnect = function()
    tp_reconnect_state.armed = false
    tp_reconnect_state.next_try_at = 0
    tp_reconnect_state.attempts = 0
    tp_reconnect_state.sent_for_disconnect = false
    tp_reconnect_state.reconnect_in_progress = false
    tp_reconnect_state.internal_command = false
end

tp_note_reconnect_progress = function()
    tp_reconnect_state.armed = false
    tp_reconnect_state.reconnect_in_progress = true
    tp_reconnect_state.sent_for_disconnect = true
    tp_reconnect_state.next_try_at = 0
end

local function tp_try_issue_reconnect()
    tp_reconnect_state.internal_command = true
    local ok = pcall(sampProcessChatInput, '/rec')
    if not ok then
        pcall(sampSendChat, '/rec')
    end
    tp_reconnect_state.internal_command = false
end

tp_schedule_auto_reconnect = function()
    if not cVARS.auto_reconnect_enabled[0] or not tp_state.connection_closed then
        tp_reset_reconnect()
        return
    end
    tp_clear_manual_reconnect_request()
    if tp_reconnect_state.sent_for_disconnect or tp_reconnect_state.reconnect_in_progress then
        return
    end
    tp_reconnect_state.disconnect_serial = tp_state.session
    tp_reconnect_state.armed = true
    tp_reconnect_state.attempts = 0
    tp_reconnect_state.next_try_at = os.clock() + 1.25
end

tp_process_auto_reconnect = function(spawn_ready)
    if spawn_ready and not tp_state.connection_closed then
        tp_reset_reconnect()
        return
    end
    if tp_reconnect_state.reconnect_in_progress then
        return
    end
    if not cVARS.auto_reconnect_enabled[0] or not tp_reconnect_state.armed then
        return
    end
    if not tp_state.connection_closed then
        tp_reset_reconnect()
        return
    end
    if tp_reconnect_state.disconnect_serial ~= tp_state.session then
        tp_reset_reconnect()
        return
    end
    if os.clock() < tp_reconnect_state.next_try_at then
        return
    end

    tp_reconnect_state.attempts = tp_reconnect_state.attempts + 1
    tp_reconnect_state.sent_for_disconnect = true
    tp_reconnect_state.reconnect_in_progress = true
    tp_try_issue_reconnect()
    tp_reconnect_state.armed = false
end

local MOUSEEVENTF_LEFTDOWN = 0x0002
local MOUSEEVENTF_LEFTUP = 0x0004

local TP_CLOSE_WORDS = {
    "Закры", "закры", "close", "Close", "skip", "Skip", "Пропус", "пропус", "Позже", "позже"
}

local TP_ACCEPT_WORDS = {
    "Окей", "окей", "ОК", "Ок", "ок",
    "Выдвига", "выдвига",
    "Продолж", "продолж",
    "Отправ", "отправ",
    "Принять", "принять",
    "Перейти", "перейти",
    "Поех", "поех"
}

local TP_AD_HINTS = {
    "BATTLEPASS", "BattlePass", "battlepass",
    "PayDay", "payday",
    "Кейс", "кейс",
    "Донат", "донат",
    "Скин", "скин",
    "Автомобиль", "автомобиль",
    "Mansory", "McLaren", "BMW"
}

local TP_QUEST_HINTS = {
    "паспорт", "Паспорт",
    "Марию", "марию",
    "Мэрию", "мэрию",
    "миникарте", "Миникарте",
    "задание", "Задание",
    "выдвигаюсь", "Выдвигаюсь"
}

local function tp_mouse_click_screen(x, y)
    pcall(ffi.C.SetCursorPos, x, y)
    wait(25)
    pcall(ffi.C.mouse_event, MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0)
    wait(25)
    pcall(ffi.C.mouse_event, MOUSEEVENTF_LEFTUP, 0, 0, 0, 0)
end

local function tp_click_norm(nx, ny)
    local sx, sy = getScreenResolution()
    local x = math.floor(sx * nx)
    local y = math.floor(sy * ny)
    tp_mouse_click_screen(x, y)
end

local function tp_click_points(points, delay_ms)
    if not points then
        return
    end
    for i = 1, #points do
        local p = points[i]
        tp_click_norm(p[1], p[2])
        if delay_ms and i < #points then
            wait(delay_ms)
        end
    end
end

local function tp_contains_any(haystack, words)
    haystack = tostring(haystack or "")
    if haystack == "" then
        return false
    end
    for _, word in ipairs(words) do
        if haystack:find(word, 1, true) then
            return true
        end
    end
    return false
end

tp_pick_dialog_button = function(title, button1, button2, text)
    local hay = table.concat({
        tostring(title or ""),
        tostring(button1 or ""),
        tostring(button2 or ""),
        tostring(text or "")
    }, "\n")

    local b1_close = tp_contains_any(button1, TP_CLOSE_WORDS)
    local b2_close = tp_contains_any(button2, TP_CLOSE_WORDS)
    local b1_accept = tp_contains_any(button1, TP_ACCEPT_WORDS)
    local b2_accept = tp_contains_any(button2, TP_ACCEPT_WORDS)
    local looks_like_ad = tp_contains_any(hay, TP_AD_HINTS)
    local looks_like_quest = tp_contains_any(hay, TP_QUEST_HINTS)

    if looks_like_ad then
        if b1_close then return 1 end
        if b2_close then return 0 end
    end

    if looks_like_quest then
        if b1_accept then return 1 end
        if b2_accept then return 0 end
    end

    if b1_close then return 1 end
    if b2_close then return 0 end
    if b1_accept then return 1 end
    if b2_accept then return 0 end

    return 1
end

tp_trigger_overlay_buttons = function(now)
    if not tp_should_guard_ui() then
        return
    end
    now = now or os.clock()
    if (now - tp_auto_state.last_overlay_click_at) < TP_OVERLAY_CLICK_INTERVAL then
        return
    end

    tp_auto_state.last_overlay_click_at = now
    tp_auto_state.popup_seen = true
    tp_auto_state.last_activity_at = now

    lua_thread.create(function()
        if not tp_should_guard_ui() then
            return
        end

        -- 1) Закрываем battlepass/promo сверху справа.
        tp_click_points(TP_OVERLAY_CLOSE_POINTS, 60)
        wait(140)

        if not tp_should_guard_ui() then
            return
        end

        -- 2) Жмем только маленькую кнопку диалога бота внизу (Да! / Окей, выдвигаюсь).
        tp_click_points(TP_OVERLAY_DIALOG_POINTS, 50)
    end)
end

tp_reset_auto_schedule = function()
    tp_auto_state.armed = false
    tp_auto_state.trigger_at = 0
    tp_auto_state.cleanup_active = false
    tp_auto_state.cleanup_deadline = 0
    tp_auto_state.cleanup_started_at = 0
    tp_auto_state.last_activity_at = 0
    tp_auto_state.last_enter_at = 0
    tp_auto_state.popup_seen = false
    tp_auto_state.close_pending = false
    tp_auto_state.close_reason = nil
    tp_auto_state.cursor_visible = false
    tp_auto_state.last_overlay_click_at = 0
end

tp_press_virtual_key = function(vk)
    lua_thread.create(function()
        setVirtualKeyDown(vk, true)
        wait(60)
        setVirtualKeyDown(vk, false)
    end)
end

tp_is_os_cursor_visible = function()
    local info = ffi.new('CURSORINFO')
    info.cbSize = ffi.sizeof(info)
    local ok = pcall(function() return ffi.C.GetCursorInfo(info) end)
    if not ok then
        return false
    end
    return tonumber(info.flags) == 1
end

tp_should_guard_ui = function()
    return cVARS.auto_teleport_enabled[0]
       and tp_is_spawn_ready()
       and not tp_state.connection_closed
       and (tp_auto_state.cleanup_active or tp_state.active or tp_state.pending)
end

tp_note_spawn_ui_activity = function()
    if not tp_should_guard_ui() then
        return
    end
    tp_auto_state.popup_seen = true
    tp_auto_state.last_activity_at = os.clock()
end

tp_request_ui_close = function(reason)
    if not tp_should_guard_ui() then
        return
    end
    tp_note_spawn_ui_activity()
    tp_auto_state.close_pending = true
    tp_auto_state.close_reason = reason
end

tp_handle_ui_guard = function()
    if not tp_should_guard_ui() then
        tp_auto_state.close_pending = false
        tp_auto_state.cursor_visible = false
        tp_auto_state.last_overlay_click_at = 0
        return
    end

    local now = os.clock()
    local cursor_visible = false
    local ok_cursor, visible = pcall(tp_is_os_cursor_visible)
    if ok_cursor and visible and not cVARS.menu[0] then
        cursor_visible = true
    end

    if cursor_visible ~= tp_auto_state.cursor_visible then
        tp_auto_state.cursor_visible = cursor_visible
        tp_auto_state.last_activity_at = now
    end

    if cursor_visible then
        tp_trigger_overlay_buttons(now)
        return
    end

    if not tp_auto_state.controllable and (now - tp_auto_state.last_enter_at) >= 1.00 then
        tp_note_spawn_ui_activity()
        tp_auto_state.last_enter_at = now
        tp_press_virtual_key(13)
    end
end

tp_begin_spawn_cleanup = function()
    tp_reset_auto_schedule()
    if not cVARS.auto_teleport_enabled[0] then
        return
    end
    if tp_state.active or tp_state.pending or tp_state.connection_closed then
        return
    end
    local now = os.clock()
    tp_auto_state.controllable = true
    tp_auto_state.cleanup_active = true
    tp_auto_state.cleanup_deadline = now + TP_SPAWN_CLEANUP_WINDOW
    tp_auto_state.cleanup_started_at = now
    tp_auto_state.last_activity_at = now
    tp_auto_state.last_enter_at = 0
    tp_auto_state.popup_seen = false
    tp_auto_state.close_pending = false
    tp_auto_state.close_reason = nil
    tp_auto_state.cursor_visible = false
    tp_auto_state.last_overlay_click_at = 0
end

tp_finish_spawn_cleanup = function(arm_after)
    local can_arm = arm_after and cVARS.auto_teleport_enabled[0] and not tp_state.connection_closed and tp_is_spawn_ready() and not tp_state.active and not tp_state.pending
    tp_auto_state.cleanup_active = false
    tp_auto_state.cleanup_deadline = 0
    tp_auto_state.cleanup_started_at = 0
    tp_auto_state.last_activity_at = 0
    tp_auto_state.last_enter_at = 0
    tp_auto_state.popup_seen = false
    tp_auto_state.close_pending = false
    tp_auto_state.close_reason = nil
    tp_auto_state.cursor_visible = false
    tp_auto_state.last_overlay_click_at = 0
    if can_arm then
        tp_arm_auto_schedule()
    else
        tp_auto_state.armed = false
        tp_auto_state.trigger_at = 0
    end
end

tp_is_spawn_ready = function()
    if not isSampAvailable() then
        return false
    end
    if sampGetGamestate() ~= 3 then
        return false
    end
    if not doesCharExist(PLAYER_PED) or isCharDead(PLAYER_PED) then
        return false
    end
    if type(sampIsLocalPlayerSpawned) == 'function' then
        local ok, spawned = pcall(sampIsLocalPlayerSpawned)
        if ok and not spawned then
            return false
        end
    end
    return true
end

tp_arm_auto_schedule = function()
    if not cVARS.auto_teleport_enabled[0] then
        tp_reset_auto_schedule()
        return
    end
    if tp_state.active or tp_state.pending or tp_auto_state.cleanup_active then
        return
    end
    tp_auto_state.armed = true
    tp_auto_state.trigger_at = os.clock() + TP_AUTOTP_DELAY
end

tp_mark_connection_closed = function(reason, schedule_reconnect)
    if tp_state.connection_closed then
        if schedule_reconnect == false then
            tp_reset_reconnect()
        elseif schedule_reconnect == true then
            tp_schedule_auto_reconnect()
        end
        return
    end
    tp_state.connection_closed = true
    tp_cancel_all(reason or "отмена телепорта из-за закрытия соединения")
    if schedule_reconnect == false then
        tp_reset_reconnect()
    else
        tp_schedule_auto_reconnect()
    end
end

local function tp_should_abort(session)
    if tp_state.cancel_requested then
        return true
    end
    if tp_state.connection_closed then
        return true
    end
    if session ~= nil and tp_state.session ~= session then
        return true
    end
    if not isSampAvailable() then
        return true
    end
    if sampGetGamestate() ~= 3 then
        return true
    end
    if not tp_is_spawn_ready() then
        return true
    end
    return false
end

local function tp_abort_if_needed(session)
    if tp_should_abort(session) then
        error(TP_ABORT_TOKEN)
    end
end

tp_cancel_all = function(reason)
    local had_active = tp_state.active or tp_state.pending or tp_auto_state.armed or tp_auto_state.cleanup_active
    tp_state.cancel_requested = true
    tp_state.session = tp_state.session + 1
    tp_state.active = false
    tp_state.pending = false
    tp_reset_auto_schedule()
    tp_auto_state.close_pending = false

    if doesCharExist(PLAYER_PED) then
        if isCharInAnyCar(PLAYER_PED) then
            local vehicle_handle = storeCarCharIsInNoSave(PLAYER_PED)
            if vehicle_handle and vehicle_handle ~= 0 then
                pcall(freezeCarPosition, vehicle_handle, false)
            end
        end
        pcall(freezeCharPosition, PLAYER_PED, false)
    end

    if reason and had_active then
        tp_chat(reason)
    end
end

local function tp_get_mode_snapshot()
    local in_car = isCharInAnyCar(PLAYER_PED)
    local vehicle_handle = nil
    if in_car then
        vehicle_handle = storeCarCharIsInNoSave(PLAYER_PED)
    end
    return in_car, vehicle_handle
end

local function tp_get_entity_coordinates(in_car, vehicle_handle)
    if in_car and vehicle_handle ~= nil then
        return getCarCoordinates(vehicle_handle)
    end
    return getCharCoordinates(PLAYER_PED)
end

local function tp_set_entity_coordinates(in_car, vehicle_handle, x, y, z)
    if in_car and vehicle_handle ~= nil then
        setCarCoordinates(vehicle_handle, x, y, z)
    else
        setCharCoordinates(PLAYER_PED, x, y, z)
    end
end

local function tp_set_frozen(in_car, vehicle_handle, value)
    if in_car and vehicle_handle ~= nil then
        freezeCarPosition(vehicle_handle, value)
    else
        freezeCharPosition(PLAYER_PED, value)
    end
end

local function tp_step_move(in_car, vehicle_handle, x, y, z, wait_ms, session)
    tp_abort_if_needed(session)
    if tp_state and tp_state.active then
        pcall(tp_set_frozen, in_car, vehicle_handle, true)
    end

    tp_set_entity_coordinates(in_car, vehicle_handle, x, y, z)
    tp_abort_if_needed(session)

    if tp_state and tp_state.active then
        pcall(tp_set_frozen, in_car, vehicle_handle, true)
    end

    wait(wait_ms or 300)
    tp_abort_if_needed(session)

    if tp_state and tp_state.active then
        pcall(tp_set_frozen, in_car, vehicle_handle, true)
    end
end

local function tp_request_target_scene(x, y, z)
    requestCollision(x, y)
    loadScene(x, y, z)
end

local function tp_probe_ground_z(x, y, probe_z)
    if type(getGroundZFor3dCoord) ~= 'function' then
        return false, nil
    end

    local ok, r1, r2 = pcall(getGroundZFor3dCoord, x, y, probe_z)
    if not ok then
        return false, nil
    end

    if type(r1) == 'boolean' then
        if r1 and type(r2) == 'number' then
            return true, r2
        end
        return false, nil
    end

    if type(r1) == 'number' then
        return true, r1
    end

    return false, nil
end

local function tp_push_ground_candidate(out, px, py, pz)
    if pz == nil or pz <= -1000.0 or pz >= 2000.0 then
        return
    end

    for _, candidate in ipairs(out) do
        if getDistanceBetweenCoords2d(candidate.x, candidate.y, px, py) <= 0.15 and math.abs(candidate.z - pz) <= 0.75 then
            return
        end
    end

    out[#out + 1] = { x = px, y = py, z = pz }
end

local function tp_collect_ground_candidates(x, y, fallback_z)
    local radius = 1.5
    local diag = radius * 0.7
    local points = {
        { 0.0, 0.0 },
        { radius, 0.0 }, { -radius, 0.0 },
        { 0.0, radius }, { 0.0, -radius },
        { diag, diag }, { -diag, diag },
        { diag, -diag }, { -diag, -diag },
    }
    local probes = {
        math.max(fallback_z + 40.0, 120.0),
        math.max(fallback_z + 120.0, 220.0),
        420.0,
        700.0,
        1000.0,
    }
    local candidates = {}

    for _, point in ipairs(points) do
        local px = x + point[1]
        local py = y + point[2]

        for _, probe_z in ipairs(probes) do
            tp_request_target_scene(px, py, probe_z)
            wait(60)

            local found, ground_z = tp_probe_ground_z(px, py, probe_z)
            if found then
                tp_push_ground_candidate(candidates, px, py, ground_z)
            end
        end
    end

    return candidates
end

local function tp_choose_ground_candidate(target_x, target_y, fallback_z, candidates)
    if #candidates == 0 then
        return target_x, target_y, fallback_z + 1.0
    end

    local near = {}
    for _, candidate in ipairs(candidates) do
        if math.abs(candidate.z - fallback_z) <= 18.0 then
            near[#near + 1] = candidate
        end
    end

    local prefer_near = #near > 0
    local source = prefer_near and near or candidates

    table.sort(source, function(a, b)
        if not prefer_near and math.abs(a.z - b.z) > 0.01 then
            return a.z > b.z
        end

        local da = getDistanceBetweenCoords2d(target_x, target_y, a.x, a.y)
        local db = getDistanceBetweenCoords2d(target_x, target_y, b.x, b.y)
        if math.abs(da - db) > 0.01 then
            return da < db
        end

        return a.z > b.z
    end)

    local best = source[1]
    return best.x, best.y, best.z + 1.0
end

local function tp_resolve_surface_target(x, y, fallback_z)
    local candidates = tp_collect_ground_candidates(x, y, fallback_z)
    return tp_choose_ground_candidate(x, y, fallback_z, candidates)
end

local function tp_perform_precise_vertical_travel(in_car, vehicle_handle, x, y, from_z, to_z)
    local step = 4.0
    local packets = math.max(1, math.ceil(math.abs(from_z - to_z) / step))

    for index = 1, packets do
        tp_abort_if_needed(tp_state.session)
        local z = tp_lerp(from_z, to_z, index / packets)
        tp_request_target_scene(x, y, z)
        tp_step_move(in_car, vehicle_handle, x, y, z, 300, tp_state.session)
    end
end

local function tp_force_ground_lock_direct(in_car, vehicle_handle, x, y, fallback_z, transit_z)
    local land_x, land_y, land_z = tp_resolve_surface_target(x, y, fallback_z)
    local current_z = transit_z

    for _ = 1, 4 do
        tp_abort_if_needed(tp_state.session)
        land_x, land_y, land_z = tp_resolve_surface_target(land_x, land_y, land_z)

        local relock_z = math.min(land_z - 12.0, land_z - 0.75)
        if relock_z < transit_z then
            relock_z = transit_z
        end

        if math.abs(current_z - relock_z) > 0.05 then
            tp_perform_precise_vertical_travel(in_car, vehicle_handle, land_x, land_y, current_z, relock_z)
            current_z = relock_z
        end

        if math.abs(current_z - land_z) > 0.05 then
            tp_perform_precise_vertical_travel(in_car, vehicle_handle, land_x, land_y, current_z, land_z)
            current_z = land_z
        end

        tp_request_target_scene(land_x, land_y, land_z)
        wait(90)
        tp_abort_if_needed(tp_state.session)

        local verify_x, verify_y, verify_z = tp_resolve_surface_target(land_x, land_y, land_z)
        if math.abs(verify_z - land_z) <= 1.5 then
            tp_step_move(in_car, vehicle_handle, verify_x, verify_y, verify_z, 60, tp_state.session)
            return verify_x, verify_y, verify_z
        end

        land_x, land_y, land_z = verify_x, verify_y, verify_z
        local mini_lift_z = land_z + 18.0
        if math.abs(current_z - mini_lift_z) > 0.05 then
            tp_perform_precise_vertical_travel(in_car, vehicle_handle, land_x, land_y, current_z, mini_lift_z)
            current_z = mini_lift_z
        end
    end

    tp_step_move(in_car, vehicle_handle, land_x, land_y, land_z, 90, tp_state.session)
    return land_x, land_y, land_z
end

local function tp_get_base_step(in_car)
    if in_car then
        return 12.0
    end
    return 10.0
end

local function tp_estimate_segment_packets(distance, step)
    if distance <= 0.01 then
        return 0
    end

    return math.max(1, math.ceil(distance / math.max(step, 0.001)))
end

local function tp_perform_segment(in_car, vehicle_handle, sx, sy, sz, ex, ey, ez)
    local dx = ex - sx
    local dy = ey - sy
    local dz = ez - sz
    local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
    local base_step = tp_get_base_step(in_car)
    local packets = tp_estimate_segment_packets(distance, base_step)

    if packets <= 0 then
        return
    end

    for index = 1, packets do
        tp_abort_if_needed(tp_state.session)
        local t = index / packets
        local x = tp_lerp(sx, ex, t)
        local y = tp_lerp(sy, ey, t)
        local z = tp_lerp(sz, ez, t)

        if index == 1 or index == packets or (index % 6) == 0 then
            tp_request_target_scene(x, y, z)
        end

        tp_step_move(in_car, vehicle_handle, x, y, z, 300, tp_state.session)
    end
end

local function tp_clean_label_text(text)
    if not text then
        return ""
    end
    text = text:gsub("{%x%x%x%x%x%x}", "")
    text = text:gsub("\r", " ")
    text = text:gsub("\n", " ")
    text = text:gsub("%s+", " ")
    text = text:gsub("^%s+", "")
    text = text:gsub("%s+$", "")
    return text
end

local TP_JOB_LABEL_TEXT = "Устройство на работу"
local TP_JOB_LABEL_SHORT = "Устройство"

local function tp_is_exact_job_label(text)
    return text == TP_JOB_LABEL_TEXT or text:find(TP_JOB_LABEL_TEXT, 1, true) ~= nil
end

local function tp_find_job_label_near(x, y, radius, exact_only)
    local best_exact = nil
    local best_exact_dist = math.huge
    local best_partial = nil
    local best_partial_dist = math.huge

    for id = 0, 2048 do
        if sampIs3dTextDefined(id) then
            local text, color, posX, posY, posZ = sampGet3dTextInfoById(id)
            local clean_text = tp_clean_label_text(text)
            local dist2d = getDistanceBetweenCoords2d(posX, posY, x, y)
            if dist2d <= radius then
                if tp_is_exact_job_label(clean_text) then
                    if dist2d < best_exact_dist then
                        best_exact_dist = dist2d
                        best_exact = {x = posX, y = posY, z = posZ, text = clean_text, dist = dist2d}
                    end
                elseif not exact_only and clean_text:find(TP_JOB_LABEL_SHORT, 1, true) then
                    if dist2d < best_partial_dist then
                        best_partial_dist = dist2d
                        best_partial = {x = posX, y = posY, z = posZ, text = clean_text, dist = dist2d}
                    end
                end
            end
        end
    end

    return best_exact or (exact_only and nil or best_partial)
end

local function tp_wait_exact_job_label(target_x, target_y, radius, attempts, refresh_z)
    for attempt = 1, attempts do
        tp_abort_if_needed(tp_state.session)
        local label = tp_find_job_label_near(target_x, target_y, radius, true)
        if label then
            return label
        end
        tp_request_target_scene(target_x, target_y, refresh_z or TP_FARM_FALLBACK.z)
        wait(160)
        tp_abort_if_needed(tp_state.session)
    end
    tp_abort_if_needed(tp_state.session)
    return nil
end

local function tp_try_snap_to_job_label(required_radius)
    tp_abort_if_needed(tp_state.session)
    local px, py, pz = getCharCoordinates(PLAYER_PED)
    local label = tp_find_job_label_near(px, py, 30.0, true)
        or tp_find_job_label_near(px, py, 30.0, false)
        or tp_find_job_label_near(TP_FARM_FALLBACK.x, TP_FARM_FALLBACK.y, 90.0, true)
        or tp_find_job_label_near(TP_FARM_FALLBACK.x, TP_FARM_FALLBACK.y, 90.0, false)
    if not label then
        return false
    end

    local in_car, vehicle_handle = tp_get_mode_snapshot()
    local snap_x, snap_y, snap_z = tp_resolve_surface_target(label.x, label.y, label.z)
    tp_step_move(in_car, vehicle_handle, snap_x, snap_y, snap_z, 150, tp_state.session)

    local verify_label = tp_find_job_label_near(snap_x, snap_y, required_radius or 1.0, true)
    if verify_label then
        local verify_x, verify_y, verify_z = tp_resolve_surface_target(verify_label.x, verify_label.y, verify_label.z)
        tp_step_move(in_car, vehicle_handle, verify_x, verify_y, verify_z, 120, tp_state.session)
        return true
    end

    return required_radius == nil
end

local function tp_perform_farm_teleport(target_x, target_y, target_z, session)
    if tp_state.active then
        tp_chat("Телепорт уже выполняется.")
        return false
    end

    local in_car, vehicle_handle = tp_get_mode_snapshot()
    local start_x, start_y, start_z = tp_get_entity_coordinates(in_car, vehicle_handle)
    local land_x, land_y, resolved_target_z = tp_resolve_surface_target(target_x, target_y, target_z)
    local transit_z = math.min(start_z, resolved_target_z) - 45.0
    local pre_land_z = math.max(transit_z, math.min(resolved_target_z - 12.0, resolved_target_z - 0.75))

    tp_state.active = true
    tp_abort_if_needed(session)

    local ok, err = pcall(function()
        tp_abort_if_needed(session)
        tp_request_target_scene(land_x, land_y, resolved_target_z)
        wait(120)
        tp_abort_if_needed(session)

        tp_set_frozen(in_car, vehicle_handle, true)
        wait(50)
        tp_abort_if_needed(session)

        tp_perform_segment(in_car, vehicle_handle, start_x, start_y, start_z, start_x, start_y, transit_z)
        tp_perform_segment(in_car, vehicle_handle, start_x, start_y, transit_z, land_x, land_y, transit_z)

        tp_abort_if_needed(session)
        local exact_label = tp_wait_exact_job_label(land_x, land_y, 90.0, 10, transit_z)
        if exact_label then
            local exact_x, exact_y, exact_z = tp_resolve_surface_target(exact_label.x, exact_label.y, exact_label.z)
            if getDistanceBetweenCoords2d(land_x, land_y, exact_x, exact_y) > 0.05 then
                tp_perform_segment(in_car, vehicle_handle, land_x, land_y, transit_z, exact_x, exact_y, transit_z)
            end
            land_x, land_y, resolved_target_z = exact_x, exact_y, exact_z
            pre_land_z = math.max(transit_z, math.min(resolved_target_z - 12.0, resolved_target_z - 0.75))
        else
            tp_abort_if_needed(session)
            tp_chat("Точный 3D-текст не найден, поиск продолжен в зоне фарма.")
        end

        tp_abort_if_needed(session)
        local verify_label = tp_wait_exact_job_label(land_x, land_y, 1.0, 6, transit_z)
        if verify_label then
            local verify_x, verify_y, verify_z = tp_resolve_surface_target(verify_label.x, verify_label.y, verify_label.z)
            if getDistanceBetweenCoords2d(land_x, land_y, verify_x, verify_y) > 0.01 then
                tp_perform_segment(in_car, vehicle_handle, land_x, land_y, transit_z, verify_x, verify_y, transit_z)
                land_x, land_y, resolved_target_z = verify_x, verify_y, verify_z
                pre_land_z = math.max(transit_z, math.min(resolved_target_z - 12.0, resolved_target_z - 0.75))
            end
        end

        tp_abort_if_needed(session)
        tp_perform_segment(in_car, vehicle_handle, land_x, land_y, transit_z, land_x, land_y, pre_land_z)
        tp_abort_if_needed(session)
        tp_force_ground_lock_direct(in_car, vehicle_handle, land_x, land_y, resolved_target_z, pre_land_z)

        tp_abort_if_needed(session)
        wait(600)
        tp_abort_if_needed(session)
        tp_set_frozen(in_car, vehicle_handle, false)
        wait(80)
        tp_abort_if_needed(session)
    end)

    tp_set_frozen(in_car, vehicle_handle, false)
    if tp_state.session == session then
        tp_state.active = false
    end

    if not ok then
        if tostring(err) == TP_ABORT_TOKEN then
            return false, "aborted"
        end
        tp_chat("Ошибка телепорта: " .. tostring(err))
        return false, tostring(err)
    end

    if tp_should_abort(session) then
        return false, "aborted"
    end

    return true
end

function teleport_to_farm_job()
    if tp_state.active or tp_state.pending then
        tp_chat("Телепорт уже выполняется.")
        return
    end

    tp_state.cancel_requested = false
    tp_state.connection_closed = false
    tp_state.pending = true
    tp_state.session = tp_state.session + 1
    local session = tp_state.session
    tp_reset_auto_schedule()

    lua_thread.create(function()
        local ok_thread, err = pcall(function()
            tp_abort_if_needed(session)

            local target = TP_FARM_FALLBACK
            local streamed_label = tp_wait_exact_job_label(TP_FARM_FALLBACK.x, TP_FARM_FALLBACK.y, 90.0, 5, TP_FARM_FALLBACK.z)
                or tp_find_job_label_near(TP_FARM_FALLBACK.x, TP_FARM_FALLBACK.y, 90.0, false)
            if streamed_label then
                target = streamed_label
            end

            local ok = tp_perform_farm_teleport(target.x, target.y, target.z, session)
            if not ok then
                return
            end

            tp_abort_if_needed(session)
            wait(250)
            tp_abort_if_needed(session)
            tp_try_snap_to_job_label(1.0)
            tp_abort_if_needed(session)
            if not tp_should_abort(session) then
                tp_chat("Телепорт на фарм завершён.")
            end
        end)

        if tp_state.session == session then
            tp_state.pending = false
            tp_state.active = false
            if not tp_state.connection_closed then
                tp_state.cancel_requested = false
            end
        end

        if not ok_thread and tostring(err) ~= TP_ABORT_TOKEN then
            tp_chat("Ошибка запуска телепорта: " .. tostring(err))
        end
    end)
end

function cMsg(text) -- чтобы делать 5 строк при загрузке
    sampAddChatMessage("[{7208fc}Leso{6207d9}Руб{FFFFFF}] " .. text, -1)
end

