    config.camera_smooth_close = cVARS.camera_smooth_close[0]
    config.camera_smooth_mid = cVARS.camera_smooth_mid[0]
    config.camera_smooth_far = cVARS.camera_smooth_far[0]
    config.camera_dist = cVARS.camera_dist[0]
    config.menu_movable = cVARS.menu_movable[0]
    config.menu_pos_x = cVARS.menu_pos_x[0]
    config.menu_pos_y = cVARS.menu_pos_y[0]
    config.camera_height_offset = cVARS.camera_height_offset[0]
    config.menu_command = ffi.string(cVARS.menu_command)
    config.bot_command = ffi.string(cVARS.bot_command)
    config.enable_random_pauses = cVARS.enable_random_pauses[0]
    config.menu_hotkey = cVARS.menu_hotkey[0]
    config.bot_hotkey = cVARS.bot_hotkey[0]
    config.telegram_token = u8:decode(ffi.string(cVARS.telegram_token))
    config.telegram_chat_id = u8:decode(ffi.string(cVARS.telegram_chat_id))
    config.use_tree_fov = cVARS.use_tree_fov[0]
    config.check_stuck = cVARS.check_stuck[0]
    config.time_probe_enabled = cVARS.time_probe_enabled[0]
    config.time_probe_interval = clamp_time_probe_interval(cVARS.time_probe_interval[0])
    config.time_probe_show_remaining = cVARS.time_probe_show_remaining[0]
    config.auto_teleport_enabled = cVARS.auto_teleport_enabled[0]
    config.auto_reconnect_enabled = cVARS.auto_reconnect_enabled[0]
    config.random_inventory_enabled = cVARS.random_inventory_enabled[0]
    config.random_inventory_show_remaining = cVARS.random_inventory_show_remaining[0]
    config.antiadmin_play_sound = cVARS.antiadmin_play_sound[0]
    config.antiadmin_sound_path = u8:decode(ffi.string(cVARS.antiadmin_sound_path))
    config.telegram_allow_only_saved_chat = cVARS.telegram_allow_only_saved_chat[0]
    config.telegram_allow_exit = cVARS.telegram_allow_exit[0]
    config.telegram_allow_crash = cVARS.telegram_allow_crash[0]
    config.telegram_allow_chat_send = cVARS.telegram_allow_chat_send[0]
    config.state_watchdog_enabled = cVARS.state_watchdog_enabled[0]
    config.stat_status = cVARS.stat_status[0]
    config.derevo_value = cVARS.derevo_value[0]
    config.derevo_amount = cVARS.derevo_amount[0]
    config.rainbowcolor = cVARS.rainbowcolor[0]
    local combo_str = ""
    if cVARS.combo_key1[0] and cVARS.combo_key1[0] ~= 0 then
        combo_str = getKeyName(cVARS.combo_key1[0])
        if cVARS.combo_key2[0] and cVARS.combo_key2[0] ~= 0 then
            combo_str = combo_str .. "+" .. getKeyName(cVARS.combo_key2[0])
        end
    end
    config.menu_hotkey_combo = combo_str
    local cfg_path = getWorkingDirectory() .. "\\config\\lesorub_flupiflufi.json"
    local cfg_json = encodeJson(config)
    local ok, err = write_text_file_atomic(cfg_path, cfg_json)
    if not ok then
        error('save_cfg failed: ' .. tostring(err))
    end
end
function onScriptTerminate(script, quitGame)
    if script == thisScript() then
        flush_save_cfg_if_needed(true)
    end
end
